/* ===== ELECTRICAL — additive data, diagrams and calculators (ids prefixed el-) ===== */
const ELRHO_CU20 = 1.7241e-8, ELRHO_AL20 = 2.826e-8, ELALPHA_CU = 0.00393, ELALPHA_AL = 0.00429;
const elSizeList = ['30', '28', '26', '24', '22', '20', '18', '16', '14', '12', '10', '8', '6', '4', '3', '2', '1', '1/0', '2/0', '3/0', '4/0', '250', '300', '350', '400', '500', '600', '750', '1000'];
const elAwgNum = s => ({ '1/0': 0, '2/0': -1, '3/0': -2, '4/0': -3 }[s] !== undefined ? { '1/0': 0, '2/0': -1, '3/0': -2, '4/0': -3 }[s] : Number(s));
const elDiaMm = n => 0.127 * Math.pow(92, (36 - n) / 39);
const elAreaOf = s => Number(s) >= 250 ? Number(s) * 0.506707479 : Math.PI / 4 * Math.pow(elDiaMm(elAwgNum(s)), 2);
const elSizeLabel = s => Number(s) >= 250 ? s + ' kcmil' : 'AWG ' + s;
const elAwgName = n => n === 0 ? '1/0' : n === -1 ? '2/0' : n === -2 ? '3/0' : n === -3 ? '4/0' : String(n);
const elRkm = (A, rho) => rho * 1e9 / A;          /* ohm/km from area mm2 and resistivity ohm·m */
const elTemp = (R20, a, T) => R20 * (1 + a * (T - 20));
const elSizeSel = (k, l, def) => SEL(k, l, elSizeList.map(s => [Number(elAreaOf(s).toFixed(4)), elSizeLabel(s)]), Number(elAreaOf(def).toFixed(4)));
const elNearest = A => { const n = 36 - 39 * Math.log(Math.sqrt(4 * A / Math.PI) / 0.127) / Math.log(92); if (A >= 120) { const k = A / 0.506707479; return { n, label: Math.round(k) + ' kcmil (≈ ' + k.toFixed(0) + ')' }; } return { n, label: 'AWG ' + elAwgName(Math.round(n)) }; };
/* zig-zag resistor, horizontal, centred on y */
const elR = (x, y, w, lab) => { const s = w * 0.7 / 6; let p = `M${x} ${y} h${w * 0.15} l${s / 2} -9`; for (let i = 0; i < 5; i++) p += ` l${s} ${i % 2 ? -18 : 18}`; p += ` l${s / 2} -9 h${w * 0.15}`; return `<path d="${p}"/>` + TX(x + w / 2, y - 16, lab, { c: ACC }); };
/* zig-zag resistor, vertical, centred on x */
const elRv = (x, y, h, lab) => { const s = h * 0.7 / 6; let p = `M${x} ${y} v${h * 0.15} l-9 ${s / 2}`; for (let i = 0; i < 5; i++) p += ` l${i % 2 ? -18 : 18} ${s}`; p += ` l-9 ${s / 2} v${h * 0.15}`; return `<path d="${p}"/>` + TX(x + 22, y + h / 2 + 4, lab, { c: ACC, a: 'start' }); };
const elBat = (x, y, h, lab) => `<line x1="${x - 14}" y1="${y + h / 2 - 6}" x2="${x + 14}" y2="${y + h / 2 - 6}"/><line x1="${x - 8}" y1="${y + h / 2 + 6}" x2="${x + 8}" y2="${y + h / 2 + 6}" stroke-width="3"/>` + TX(x + 20, y + h / 2 - 8, '+', { a: 'start', c: ACC }) + TX(x - 22, y + h / 2 + 4, lab, { a: 'end', c: ACC2 });
const elArrow = (x, y, dir, c) => { const d = { r: [[x, y], [x - 8, y - 4], [x - 8, y + 4]], l: [[x, y], [x + 8, y - 4], [x + 8, y + 4]], u: [[x, y], [x - 4, y + 8], [x + 4, y + 8]], d: [[x, y], [x - 4, y - 8], [x + 4, y - 8]] }[dir]; return `<polygon points="${d.map(p => p.join(',')).join(' ')}" fill="${c || ACC}" stroke="none"/>`; };

