calc({ id: 'ex-cap-calc', title: 'Capacitor calculations: charge, energy, plate geometry, dV/dt', desc: 'Choose what to compute', kw: ['capacitor energy', 'charge on a capacitor', 'parallel plate capacitor', 'capacitance from geometry', 'dielectric constant', 'capacitor current', 'supercapacitor runtime', 'capacitor dV/dt', 'permittivity'], fields: [SEL('m', 'Compute', [['qe', 'Charge and energy (C, V)'], ['plate', 'Parallel-plate capacitance (area, gap, εr)'], ['dv', 'Charge / discharge rate (C, I)']], 'qe'), F('c', 'Capacitance C (for charge / energy / rate)', '470u', 'F', { txt: 1, opt: 1 }), F('v', 'Voltage', 12, 'V', { opt: 1 }), F('i', 'Current (for rate)', '20m', 'A', { txt: 1, opt: 1 }), F('a', 'Plate area', 100, 'mm²', { opt: 1 }), F('d', 'Plate gap', 0.1, 'mm', { opt: 1 }), F('er', 'Relative permittivity εr', 4.5, '', { opt: 1 })],
  run: v => { if (v.m === 'plate') { if (!(v.a > 0 && v.d > 0 && v.er > 0)) return 'Enter area, gap and εr.'; const C = 8.8541878128e-12 * v.er * (v.a * 1e-6) / (v.d * 1e-3); return [['Capacitance C = ε0·εr·A/d', xEng(C, 'F')], ['In pF', C * 1e12, 'pF'], 'Ideal parallel plates; fringing field adds a little. εr: vacuum 1, air 1.0006, PTFE 2.1, polyethylene 2.3, FR-4 4.5, glass 5–7, X7R ceramic 2000–4000, mica 6.']; } const C = xN(v.c); if (!(C > 0)) return 'Enter a capacitance (e.g. 470u, 4.7n).'; if (v.m === 'qe') { if (!(v.v > 0)) return 'Enter a voltage.'; return [['Charge Q = C·V', xEng(C * v.v, 'C')], ['Energy E = ½·C·V²', xEng(0.5 * C * v.v * v.v, 'J')], ['Energy', 0.5 * C * v.v * v.v / 3600 * 1000, 'mWh'], ['Equivalent time at 1 W', xEng(0.5 * C * v.v * v.v, 's')], 'A capacitor stores little energy compared with a battery (1 F at 5 V = 12.5 J ≈ 3.5 mWh), but delivers it fast. Stored energy in large capacitors can be lethal: discharge through a resistor before handling.']; } const I = xN(v.i); if (!(I > 0)) return 'Enter a current.'; const dv = I / C; const out = [['Voltage change dV/dt = I/C', xEng(dv, 'V/s')]]; if (v.v > 0) out.push(['Time to change by V (constant current)', xEng(v.v / dv, 's')]); out.push('Constant-current charging/discharging gives a linear ramp, unlike the RC exponential.'); return out; } });
calc({ id: 'ex-ind-calc', title: 'Inductor calculations: solenoid inductance, energy, di/dt', desc: 'Estimate coil inductance from geometry, or energy and voltage for a given current', kw: ['inductance calculation', 'solenoid inductance', 'coil inductance', 'inductor energy', 'air core coil', 'inductor voltage', 'turns count', 'Wheeler formula'], fields: [SEL('m', 'Compute', [['sol', 'Air-core / cored solenoid inductance'], ['en', 'Energy at a given current'], ['vd', 'Induced voltage V = L·di/dt']], 'sol'), F('n', 'Turns N', 100, '', { opt: 1 }), F('d', 'Coil diameter', 10, 'mm', { opt: 1 }), F('len', 'Coil length', 20, 'mm', { opt: 1 }), F('mu', 'Relative permeability μr', 1, '', { opt: 1 }), F('l', 'Inductance L (for energy and di/dt)', '100u', 'H', { txt: 1, opt: 1 }), F('i', 'Current', 1, 'A', { opt: 1 }), F('dt', 'Time for the current change', '1m', 's', { txt: 1, opt: 1 })],
  run: v => { if (v.m === 'sol') { if (!(v.n > 0 && v.d > 0 && v.len > 0 && v.mu > 0)) return 'Enter turns, diameter, length and μr.'; const A = Math.PI * Math.pow(v.d / 2000, 2), l = v.len / 1000, L = 4e-7 * Math.PI * v.mu * v.n * v.n * A / l; const wh = (v.d / 25.4 / 2) * (v.d / 25.4 / 2) * v.n * v.n / (9 * (v.d / 25.4 / 2) + 10 * (v.len / 25.4)) ; return [['Inductance L = μ0·μr·N²·A/l', xEng(L, 'H')], ['Wheeler approximation (air core, µH)', wh, 'µH'], ['Cross-section A', A * 1e6, 'mm²'], 'The long-solenoid formula is accurate when length ≫ diameter; short coils (like the default) are closer to the Wheeler value. Cored inductors saturate and their μr varies with current and frequency.']; } const L = xN(v.l); if (!(L > 0)) return 'Enter an inductance (e.g. 100u, 4.7m).'; if (v.m === 'en') { if (!(v.i >= 0)) return 'Enter a current.'; return [['Energy E = ½·L·I²', xEng(0.5 * L * v.i * v.i, 'J')], ['Flux linkage λ = L·I', xEng(L * v.i, 'Wb')], 'Opening the circuit forces this energy somewhere: spark, flyback diode, snubber or voltage spike.']; } const dt = xN(v.dt); if (!(dt > 0)) return 'Enter a time interval (e.g. 1m).'; return [['Induced voltage V = L·ΔI/Δt', xEng(L * v.i / dt, 'V')], 'Voltage across an inductor when its current changes by the entered amount in that time (sign: opposes the change).']; } });
const xLogicEval = (src, vars) => {
  const toks = String(src).toUpperCase().replace(/NAND/g, ' @ ').replace(/XNOR/g, ' # ').replace(/NOR/g, ' $ ').replace(/XOR/g, ' ^ ').replace(/AND/g, ' & ').replace(/OR/g, ' | ').replace(/NOT/g, ' ! ').replace(/[·*]/g, ' & ').replace(/[+]/g, ' | ').replace(/[~¬]/g, ' ! ').replace(/⊕/g, ' ^ ').match(/[A-H]|[01]|[()!&|^@#$']/g);
  if (!toks) throw new Error('empty');
  /* postfix ' means NOT on previous operand */
  let pos = 0; const peek = () => toks[pos], next = () => toks[pos++];
  const prim = env => { const t = next(); let v; if (t === '(') { v = orx(env); if (next() !== ')') throw new Error('missing )'); } else if (t === '!') v = !prim(env); else if (t === '0' || t === '1') v = t === '1'; else if (/^[A-H]$/.test(t)) { if (!(t in env)) throw new Error('unknown variable ' + t); v = !!env[t]; } else throw new Error('unexpected ' + (t || 'end')); while (peek() === "'") { next(); v = !v; } return v; };
  const andx = env => { let v = prim(env); while (peek() === '&' || peek() === '@') { const o = next(), r = prim(env); v = o === '&' ? (v && r) : !(v && r); } return v; };
  const xorx = env => { let v = andx(env); while (peek() === '^' || peek() === '#') { const o = next(), r = andx(env); v = o === '^' ? (v !== r) : (v === r); } return v; };
  const orx = env => { let v = xorx(env); while (peek() === '|' || peek() === '$') { const o = next(), r = xorx(env); v = o === '|' ? (v || r) : !(v || r); } return v; };
  const used = [...new Set(toks.filter(t => /^[A-H]$/.test(t)))].sort();
  return { used, run: env => { pos = 0; const r = orx(env); if (pos < toks.length) throw new Error('unexpected ' + toks[pos]); return r; } };
};
calc({ id: 'ex-logic', title: 'Boolean expression evaluator: truth table, minterms and equivalence', desc: 'Variables A–H; operators AND OR NOT XOR NAND NOR XNOR or & | ! ^ + · ′ ; parentheses', kw: ['truth table', 'boolean expression', 'logic expression', 'minterms', 'sum of products', 'De Morgan', 'logic equivalence', 'boolean algebra calculator', 'canonical form', 'XOR from NAND'], fields: [F('e', 'Expression', 'A XOR B', '', { txt: 1 }), F('e2', 'Compare with (optional)', '', '', { txt: 1, opt: 1 })],
  run: v => { let ev; try { ev = xLogicEval(v.e); } catch (e) { return { err: 'Cannot read the expression: ' + e.message + '. Example: (A AND B) OR NOT C' }; } const U = ev.used; if (U.length === 0) return { err: 'Use variables A to H.' }; if (U.length > 5) return { err: 'Use at most 5 variables.' }; let ev2 = null; if (v.e2 && String(v.e2).trim()) { try { ev2 = xLogicEval(v.e2); } catch (e) { return { err: 'Second expression: ' + e.message }; } } const all = ev2 ? [...new Set([...U, ...ev2.used])].sort() : U; if (all.length > 5) return { err: 'Use at most 5 variables in total.' }; const rows = [], mins = []; let ok = true; for (let m = 0; m < (1 << all.length); m++) { const env = {}; all.forEach((x, i) => env[x] = (m >> (all.length - 1 - i)) & 1); let r, r2 = null; try { r = ev.run(env); if (ev2) r2 = ev2.run(env); } catch (e) { return { err: 'Cannot evaluate: ' + e.message }; } if (r) mins.push(m); if (ev2 && r !== r2) ok = false; rows.push([all.map(x => x + '=' + env[x]).join(' '), (r ? '1' : '0') + (ev2 ? '   /   ' + (r2 ? '1' : '0') : '')]); } const n = 1 << all.length, sop = mins.length === 0 ? '0' : mins.length === n ? '1' : mins.map(m => all.map((x, i) => ((m >> (all.length - 1 - i)) & 1) ? x : x + '′').join('')).join(' + '); const out = [['Variables', all.join(', ')], ['Number of 1s in the output', mins.length + ' of ' + n], ['Minterms Σm(…)', mins.length ? mins.join(', ') : 'none'], ['Maxterms ΠM(…)', [...Array(n).keys()].filter(m => !mins.includes(m)).join(', ') || 'none'], ['Canonical sum of products', sop], ['Type', mins.length === n ? 'Tautology (always 1)' : mins.length === 0 ? 'Contradiction (always 0)' : 'Contingent (depends on inputs)']]; if (ev2) out.push(['Equivalent to the second expression?', ok ? 'YES: identical truth tables' : 'NO: they differ']); out.push(['—', ev2 ? 'Rows: inputs → expression 1 / expression 2' : 'Rows: inputs → output']); rows.forEach(r => out.push(r)); return out; } });
/* ===== CATEGORY 3b: ELECTRONICS ===== */
const CLR = [['black', 0], ['brown', 1], ['red', 2], ['orange', 3], ['yellow', 4], ['green', 5], ['blue', 6], ['violet', 7], ['gray', 8], ['white', 9]];
