/* ===== General Science: calculators (additive) ===== */
const sSigPos = s => { s = String(s).trim().toLowerCase().replace(/^[+-]/, ''); let m = s, e = 0; const k = s.indexOf('e'); if (k >= 0) { m = s.slice(0, k); e = parseInt(s.slice(k + 1), 10) || 0; } if (!/^\d*\.?\d*$/.test(m) || !/\d/.test(m)) return null; let digs, pos; if (m.includes('.')) { const [a, b] = m.split('.'); const all = (a + b).replace(/^0+/, ''); digs = all.length || 1; pos = -b.length + e; if (!all.length) { digs = b.length; } } else { const t = m.replace(/^0+/, '').replace(/0+$/, ''); const z = m.replace(/^0+/, '').length - t.length; digs = t.length || 1; pos = z + e; } return { sf: digs, pos }; };
calc({ id: 'sci-sigops', title: 'Significant figures in a calculation', desc: 'Type numbers as written (keep trailing zeros, e.g. 12.50). Whole numbers ending in zeros count those zeros as not significant.', kw: ['significant figures', 'sig fig rules', 'rounding in calculations', 'add subtract multiply divide significant'],
  fields: [F('a', 'Number A', '12.50', '', { txt: 1 }), SEL('op', 'Operation', [[1, 'A + B'], [2, 'A − B'], [3, 'A × B'], [4, 'A ÷ B']], 3), F('b', 'Number B', '3.1', '', { txt: 1 })],
  run: v => { const pa = sSigPos(v.a), pb = sSigPos(v.b); if (!pa || !pb) return { err: 'Enter plain numbers such as 12.50 or 1.2e3.' }; const A = parseFloat(v.a), B = parseFloat(v.b); const op = +v.op; if (op === 4 && B === 0) return { err: 'Cannot divide by 0.' }; const raw = op === 1 ? A + B : op === 2 ? A - B : op === 3 ? A * B : A / B; let res, note; if (op <= 2) { const p = Math.max(pa.pos, pb.pos); const q = Math.pow(10, p); const r = Math.round(raw / q) * q; res = p < 0 ? r.toFixed(-p) : String(Math.round(r)); note = 'Add/subtract: round to the least precise decimal place (10^' + p + ')'; } else { const n = Math.min(pa.sf, pb.sf); res = Number(raw.toPrecision(n)); res = res.toPrecision(n); if (/e/.test(res)) res = String(Number(res)); note = 'Multiply/divide: keep the fewest significant figures (' + n + ')'; } return [['A has', pa.sf + ' sig figs'], ['B has', pb.sf + ' sig figs'], ['Calculator result', raw], ['Rounded result', res], note]; } });
calc({ id: 'sci-prefix', title: 'SI prefix converter', desc: 'Convert a value between metric prefixes (e.g. 4.7 µF → nF)', kw: ['SI prefix', 'metric prefix', 'micro to nano', 'kilo to mega', 'convert prefix'],
  fields: [F('x', 'Value', 4.7), SEL('a', 'From prefix', [[30, 'quetta (Q) 10³⁰'], [27, 'ronna (R) 10²⁷'], [24, 'yotta (Y) 10²⁴'], [21, 'zetta (Z) 10²¹'], [18, 'exa (E) 10¹⁸'], [15, 'peta (P) 10¹⁵'], [12, 'tera (T) 10¹²'], [9, 'giga (G) 10⁹'], [6, 'mega (M) 10⁶'], [3, 'kilo (k) 10³'], [2, 'hecto (h) 10²'], [1, 'deka (da) 10¹'], [0, '(none) 10⁰'], [-1, 'deci (d) 10⁻¹'], [-2, 'centi (c) 10⁻²'], [-3, 'milli (m) 10⁻³'], [-6, 'micro (µ) 10⁻⁶'], [-9, 'nano (n) 10⁻⁹'], [-12, 'pico (p) 10⁻¹²'], [-15, 'femto (f) 10⁻¹⁵'], [-18, 'atto (a) 10⁻¹⁸'], [-21, 'zepto (z) 10⁻²¹'], [-24, 'yocto (y) 10⁻²⁴'], [-27, 'ronto (r) 10⁻²⁷'], [-30, 'quecto (q) 10⁻³⁰']], -6),
    SEL('b', 'To prefix', [[30, 'quetta (Q) 10³⁰'], [27, 'ronna (R) 10²⁷'], [24, 'yotta (Y) 10²⁴'], [21, 'zetta (Z) 10²¹'], [18, 'exa (E) 10¹⁸'], [15, 'peta (P) 10¹⁵'], [12, 'tera (T) 10¹²'], [9, 'giga (G) 10⁹'], [6, 'mega (M) 10⁶'], [3, 'kilo (k) 10³'], [2, 'hecto (h) 10²'], [1, 'deka (da) 10¹'], [0, '(none) 10⁰'], [-1, 'deci (d) 10⁻¹'], [-2, 'centi (c) 10⁻²'], [-3, 'milli (m) 10⁻³'], [-6, 'micro (µ) 10⁻⁶'], [-9, 'nano (n) 10⁻⁹'], [-12, 'pico (p) 10⁻¹²'], [-15, 'femto (f) 10⁻¹⁵'], [-18, 'atto (a) 10⁻¹⁸'], [-21, 'zepto (z) 10⁻²¹'], [-24, 'yocto (y) 10⁻²⁴'], [-27, 'ronto (r) 10⁻²⁷'], [-30, 'quecto (q) 10⁻³⁰']], -9)],
  run: v => { const d = v.a - v.b, r = v.x * Math.pow(10, d); return [['Converted value', r], ['Scientific notation', r.toExponential(4)], ['Factor applied', '10^' + d]]; } });
calc({ id: 'sci-error', title: 'Percent error and percent difference', desc: 'Compare a measured value with an accepted value, or two measurements with each other', kw: ['percent error', 'percent difference', 'relative error', 'absolute error', 'experimental error'],
  fields: [F('m', 'Measured value', 9.62), F('a', 'Accepted value', 9.80665), F('m2', 'Second measurement (optional)', '', '', { opt: 1 })],
  run: v => { if (v.a === 0) return { err: 'Accepted value cannot be 0.' }; const out = [['Absolute error', v.m - v.a], ['Relative error', (v.m - v.a) / Math.abs(v.a)], ['Percent error', Math.abs(v.m - v.a) / Math.abs(v.a) * 100, '%']]; if (v.m2 !== '' && v.m2 != null) { const mean = (v.m + v.m2) / 2; out.push(['Mean of the two', mean]); out.push(['Percent difference', mean ? Math.abs(v.m - v.m2) / Math.abs(mean) * 100 : 0, '%']); } return out; } });
calc({ id: 'sci-chain', title: 'Energy transformation chain (overall efficiency)', desc: 'Multiply the efficiency of each step; leave unused steps at 100', kw: ['efficiency', 'energy conversion', 'energy loss', 'overall efficiency', 'power plant efficiency'],
  fields: [F('e', 'Energy input', 100, 'units (any)'), F('e1', 'Step 1 efficiency', 38, '%'), F('e2', 'Step 2 efficiency', 94, '%'), F('e3', 'Step 3 efficiency', 90, '%')],
  run: v => { const f = v.e1 / 100 * v.e2 / 100 * v.e3 / 100, o = v.e * f; return [['Overall efficiency', f * 100, '%'], ['Useful output', o], ['Lost as heat', v.e - o], ['After step 1', v.e * v.e1 / 100], ['After step 2', v.e * v.e1 / 100 * v.e2 / 100]]; } });
calc({ id: 'sci-energy-units', title: 'Energy unit converter', kw: ['joule to calorie', 'kWh to joules', 'BTU', 'electronvolt', 'energy conversion'],
  fields: [F('x', 'Value', 1), SEL('u', 'Unit', [[1, 'joule (J)'], [1000, 'kilojoule (kJ)'], [4.184, 'calorie (thermochemical)'], [4184, 'kilocalorie / food Calorie'], [3600, 'watt-hour (Wh)'], [3600000, 'kilowatt-hour (kWh)'], [1055.056, 'BTU (International Table)'], [1.3558179483314004, 'foot-pound force (ft·lbf)'], [1e-7, 'erg'], [1.602176634e-19, 'electronvolt (eV)']], 4184)],
  run: v => { const J = v.x * v.u; return [['joules', J, 'J'], ['kilojoules', J / 1000, 'kJ'], ['kilocalories', J / 4184, 'kcal'], ['watt-hours', J / 3600, 'Wh'], ['kilowatt-hours', J / 3.6e6, 'kWh'], ['BTU', J / 1055.056, 'BTU'], ['ft·lbf', J / 1.3558179483314004, 'ft·lbf'], ['electronvolts', J / 1.602176634e-19, 'eV']]; } });
calc({ id: 'sci-wave', title: 'Wave calculator: frequency, wavelength, period', desc: 'Wave speed: sound in air 343 m/s at 20 °C; light in vacuum 299,792,458 m/s', kw: ['wavelength', 'frequency', 'period', 'wave speed', 'photon energy', 'angular frequency'],
  fields: [F('f', 'Frequency', 440, 'Hz'), F('v', 'Wave speed', 343, 'm/s')],
  run: v => { if (v.f <= 0 || v.v <= 0) return { err: 'Frequency and speed must be above 0.' }; const lam = v.v / v.f, E = 6.62607015e-34 * v.f; return [['Wavelength', lam, 'm'], ['Period', 1 / v.f, 's'], ['Angular frequency ω', 2 * Math.PI * v.f, 'rad/s'], ['Photon energy hf (if light)', E / 1.602176634e-19, 'eV'], ['Photon energy hf (if light)', E, 'J']]; } });
calc({ id: 'sci-doppler', title: 'Doppler effect (sound)', desc: 'f′ = f × (v + v_observer) ÷ (v − v_source). Positive speeds mean moving toward each other.', kw: ['Doppler', 'siren pitch', 'moving source', 'frequency shift'],
  fields: [F('f', 'Source frequency', 440, 'Hz'), F('v', 'Speed of sound', 343, 'm/s'), F('vo', 'Observer speed toward source', 0, 'm/s'), F('vs', 'Source speed toward observer', 30, 'm/s')],
  run: v => { if (v.v - v.vs <= 0) return { err: 'Source speed must be below the speed of sound.' }; const f2 = v.f * (v.v + v.vo) / (v.v - v.vs); return [['Observed frequency', f2, 'Hz'], ['Shift', f2 - v.f, 'Hz'], ['Observed ÷ source', f2 / v.f]]; } });
calc({ id: 'sci-snell', title: 'Refraction (Snell’s law) and critical angle', desc: 'n₁ sin θ₁ = n₂ sin θ₂ (water 1.33, glass ≈ 1.5, diamond 2.42, air 1.0003)', kw: ['Snell law', 'refraction', 'refractive index', 'critical angle', 'total internal reflection'],
  fields: [F('n1', 'Index of first medium n₁', 1), F('n2', 'Index of second medium n₂', 1.5), F('a', 'Angle of incidence', 45, '°')],
  run: v => { if (v.n1 <= 0 || v.n2 <= 0 || v.a < 0 || v.a >= 90) return { err: 'Indices must be above 0; angle 0–90°.' }; const s = v.n1 * Math.sin(v.a * D2R) / v.n2, out = []; if (s > 1) out.push('Total internal reflection: no refracted ray'); else out.push(['Refraction angle', Math.asin(s) * R2D, '°']); out.push(['Speed in medium 2', 299792458 / v.n2, 'm/s']); if (v.n1 > v.n2) out.push(['Critical angle', Math.asin(v.n2 / v.n1) * R2D, '°']); return out; } });
calc({ id: 'sci-lens', title: 'Thin lens equation', desc: '1/f = 1/d₀ + 1/dᵢ (f positive for converging lens, negative for diverging)', kw: ['lens', 'focal length', 'image distance', 'magnification', 'optics', 'camera'],
  fields: [F('f', 'Focal length', 10, 'cm'), F('d', 'Object distance', 30, 'cm')],
  run: v => { if (v.f === 0 || v.d <= 0) return { err: 'Focal length cannot be 0; object distance must be above 0.' }; if (v.f > 0 && v.d === v.f) return { err: 'Object at the focal point: image at infinity.' }; const di = 1 / (1 / v.f - 1 / v.d), m = -di / v.d; return [['Image distance', di, 'cm'], ['Magnification', m], ['Image', (di > 0 ? 'real, ' : 'virtual, ') + (m < 0 ? 'inverted, ' : 'upright, ') + (Math.abs(m) > 1 ? 'enlarged' : Math.abs(m) < 1 ? 'reduced' : 'same size')]]; } });
calc({ id: 'sci-notefreq', title: 'Musical note frequency (equal temperament)', desc: 'Semitones above A4 (negative below). A4 = 440 Hz by default.', kw: ['note frequency', 'A440', 'semitone', 'middle C', 'pitch', 'musical scale'],
  fields: [F('n', 'Semitones from A4', -9), F('r', 'Reference A4', 440, 'Hz')],
  run: v => { const n = Math.round(v.n), f = v.r * Math.pow(2, n / 12), midi = 69 + n, nm = ['C', 'C♯', 'D', 'D♯', 'E', 'F', 'F♯', 'G', 'G♯', 'A', 'A♯', 'B'][((midi % 12) + 12) % 12] + (Math.floor(midi / 12) - 1); return [['Note', nm], ['Frequency', f, 'Hz'], ['Wavelength in air (343 m/s)', 343 / f, 'm'], ['Octave up', f * 2, 'Hz']]; } });
calc({ id: 'sci-parallax', title: 'Stellar distance from parallax', desc: 'd (parsecs) = 1 ÷ parallax (arcseconds). Default: Proxima Centauri.', kw: ['parallax', 'parsec', 'light year', 'distance to star', 'stellar distance'],
  fields: [F('p', 'Parallax', 0.768, 'arcsec')],
  run: v => { if (v.p <= 0) return { err: 'Parallax must be above 0.' }; const pc = 1 / v.p; return [['Distance', pc, 'parsecs'], ['Distance', pc * 3.26156, 'light-years'], ['Distance', pc * 3.0856775814914e13, 'km'], ['Distance', pc * 206264.806, 'AU'], ['Light travel time', pc * 3.26156, 'years']]; } });
calc({ id: 'sci-angsize', title: 'Angular size and small-angle formula', desc: 'θ = size ÷ distance (radians), good for small angles. Default: the Moon.', kw: ['angular size', 'small angle', 'arcseconds', 'apparent size', 'Moon size', 'arcminutes'],
  fields: [F('s', 'Object diameter', 3474.8, 'km'), F('d', 'Distance', 384400, 'km')],
  run: v => { if (v.d <= 0) return { err: 'Distance must be above 0.' }; const th = 2 * Math.atan(v.s / (2 * v.d)); return [['Angular size', th * R2D, '°'], ['Angular size', th * R2D * 60, 'arcminutes'], ['Angular size', th * R2D * 3600, 'arcseconds'], ['Radians', th]]; } });
calc({ id: 'sci-magnitude', title: 'Stellar magnitude and brightness ratio', desc: 'A difference of 5 magnitudes = a factor of 100 in brightness; lower magnitude is brighter', kw: ['apparent magnitude', 'star brightness', 'magnitude difference', 'brightness ratio'],
  fields: [F('m1', 'Magnitude of object 1', 1), F('m2', 'Magnitude of object 2', 6)],
  run: v => { const r = Math.pow(10, 0.4 * (v.m2 - v.m1)); return [['Object 1 is brighter by', r, '×'], ['Magnitude difference', v.m2 - v.m1], v.m1 < v.m2 ? 'Object 1 is brighter' : v.m1 > v.m2 ? 'Object 2 is brighter' : 'Equal brightness']; } });
calc({ id: 'sci-moon', title: 'Moon phase for a date (approximate)', desc: 'Date YYYY-MM-DD. Uses the mean synodic month; true phase can differ by about a day.', kw: ['moon phase', 'full moon', 'new moon', 'lunar age', 'moon illumination'],
  fields: [F('d', 'Date (UTC)', '2026-11-17', '', { txt: 1 })],
  run: v => { const m = /^\s*(\d{4})-(\d{1,2})-(\d{1,2})\s*$/.exec(v.d || ''); if (!m) return { err: 'Use YYYY-MM-DD.' }; const t = Date.UTC(+m[1], +m[2] - 1, +m[3], 12); const jd = t / 864e5 + 2440587.5, S = 29.530588853; let age = (jd - 2451550.26) % S; if (age < 0) age += S; const frac = (1 - Math.cos(2 * Math.PI * age / S)) / 2, i = Math.floor(((age / S) * 8 + 0.5)) % 8; const nm = ['New moon', 'Waxing crescent', 'First quarter', 'Waxing gibbous', 'Full moon', 'Waning gibbous', 'Last quarter', 'Waning crescent'][i]; return [['Moon age', age, 'days'], ['Approx. illuminated', frac * 100, '%'], ['Phase', nm], ['Days to next full', ((S / 2 - age) % S + S) % S, 'days'], ['Days to next new', S - age, 'days']]; } });
/* ===== General Science: diagrams (original inline SVG, additive) ===== */
const sLab = (x, y, s, c) => `<text x="${x}" y="${y}" text-anchor="middle" stroke="none" fill="${c || 'currentColor'}" font-size="11">${s}</text>`;
const sSub = (x, y, s) => `<text x="${x}" y="${y}" text-anchor="middle" stroke="none" fill="${MUT}" font-size="10">${s}</text>`;
const FIG_SMETHOD = FIG(SV(340, 200, 'Scientific method as a loop: question, hypothesis, experiment, data, analysis, conclusion, then new questions',
  (() => { const b = (x, y, t, n) => `<rect x="${x}" y="${y}" width="92" height="38" rx="6" fill="var(--panel)"/>` + sLab(x + 46, y + 16, t) + `<circle cx="${x + 10}" cy="${y + 10}" r="0" />` + sSub(x + 46, y + 30, n);
    const ar = (x1, y1, x2, y2) => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${ACC}" marker-end="url(#sa)"/>`;
    return `<defs><marker id="sa" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10z" fill="${ACC}" stroke="none"/></marker></defs>` +
      b(8, 14, 'Question', 'observe, ask') + b(124, 14, 'Hypothesis', 'testable idea') + b(240, 14, 'Experiment', 'vary one thing') +
      b(240, 100, 'Data', 'measure') + b(124, 100, 'Analysis', 'graph, error') + b(8, 100, 'Conclusion', 'supported?') +
      ar(100, 33, 122, 33) + ar(216, 33, 238, 33) + ar(286, 52, 286, 98) + ar(238, 119, 218, 119) + ar(122, 119, 102, 119) +
      `<path d="M54 98 L54 60" stroke="${ACC}" marker-end="url(#sa)"/>` + sLab(170, 170, 'Repeat, refine, share results (peer review)', ACC) + sSub(170, 186, 'a conclusion often raises a new question'); })()),
  'The scientific method is a loop, not a one-way list. Conclusions are tested again by other people.');
const FIG_SACC = FIG(SV(340, 150, 'Four targets showing accuracy versus precision: accurate and precise, precise but not accurate, accurate but not precise, neither',
  (() => { const t = (cx, pts, l1, l2) => `<g transform="translate(${cx} 52)"><circle r="40" fill="var(--panel)"/><circle r="26"/><circle r="12"/><circle r="2" fill="${MUT}" stroke="none"/>${pts.map(p => `<circle cx="${p[0]}" cy="${p[1]}" r="3.2" fill="${ACC}" stroke="none"/>`).join('')}</g>` + sLab(cx, 112, l1) + sSub(cx, 126, l2);
    return t(45, [[-3, -2], [2, 3], [-1, 4], [3, -3], [0, 0]], 'Accurate', 'and precise') + t(130, [[22, 12], [26, 16], [20, 18], [25, 10], [23, 14]], 'Precise', 'not accurate') + t(215, [[-18, 8], [14, -20], [-6, 22], [22, 6], [-20, -12]], 'Accurate', 'not precise') + t(300, [[-26, 20], [18, 26], [24, -18], [-12, -28], [30, 4]], 'Neither', 'large errors'); })()),
  'Accuracy: closeness to the true value (center). Precision: closeness of repeated results to each other.');
const FIG_SWAVE = FIG(SV(340, 190, 'Anatomy of a wave: crest, trough, wavelength, amplitude and equilibrium line',
  (() => { const pts = Array.from({ length: 81 }, (_, i) => { const x = 20 + i * 3.5, y = 85 - 40 * Math.sin((i / 80) * 2 * Math.PI * 2); return x.toFixed(1) + ',' + y.toFixed(1); });
    return `<line x1="14" y1="85" x2="326" y2="85" stroke-dasharray="4 4" stroke="${MUT}"/><polyline points="${pts.join(' ')}" stroke="${ACC}" stroke-width="2.2"/>` +
      `<g stroke="${ACC2}"><line x1="55" y1="28" x2="195" y2="28"/><line x1="55" y1="22" x2="55" y2="34"/><line x1="195" y1="22" x2="195" y2="34"/></g>` + sLab(125, 18, 'wavelength λ', ACC2) +
      `<g stroke="${ACC2}"><line x1="205" y1="85" x2="205" y2="45"/><line x1="200" y1="45" x2="210" y2="45"/></g>` + sLab(262, 66, 'amplitude A', ACC2) +
      sLab(55, 40, 'crest') + sLab(125, 140, 'trough') + sLab(300, 100, 'rest', MUT) +
      sLab(170, 160, 'speed v = f × λ     period T = 1 ÷ f') + sSub(170, 176, 'f in hertz (cycles per second), λ in metres, v in m/s'); })()),
  'A wave repeats in space (wavelength) and in time (period). Amplitude sets the energy carried.');
const FIG_SSOUND = FIG(SV(340, 150, 'Sound as a longitudinal wave: regions of compression and rarefaction with a pressure curve beneath',
  (() => { let s = '', x = 14; const xs = []; for (let i = 0; i < 40; i++) { x += 7.6 + 4.2 * Math.sin(i * 2 * Math.PI / 13.3); xs.push(x); }
    s += xs.map(v => `<line x1="${v.toFixed(1)}" y1="20" x2="${v.toFixed(1)}" y2="62" stroke="currentColor" stroke-width="1.2"/>`).join('');
    const pts = Array.from({ length: 80 }, (_, i) => { const px = 14 + i * 4, y = 102 - 22 * Math.cos((px - 100) / 93 * 2 * Math.PI); return px + ',' + y.toFixed(1); });
    s += `<polyline points="${pts.join(' ')}" stroke="${ACC}" stroke-width="2"/><line x1="14" y1="102" x2="326" y2="102" stroke-dasharray="3 3" stroke="${MUT}"/>` + sLab(100, 14, 'compression', ACC2) + sLab(238, 14, 'rarefaction', ACC2) + sSub(170, 140, 'molecules vibrate along the travel direction') + sLab(300, 128, 'pressure', MUT); return s; })()),
  'Sound waves need a medium. One wavelength is the distance between successive compressions.');
const FIG_SEM = FIG(SV(340, 170, 'Electromagnetic spectrum from radio waves to gamma rays with the visible band expanded',
  (() => { const seg = [['Radio', '#8a6', 0, 68], ['Micro', '#a86', 68, 118], ['IR', '#c64', 118, 168], ['Vis', 'url(#sg)', 168, 198], ['UV', '#76c', 198, 248], ['X-ray', '#68a', 248, 298], ['γ', '#555', 298, 336]];
    return `<defs><linearGradient id="sg" x1="0" x2="1"><stop offset="0" stop-color="#7b2cbf"/><stop offset=".25" stop-color="#2a6fdb"/><stop offset=".5" stop-color="#2eb84f"/><stop offset=".72" stop-color="#f2d11c"/><stop offset=".85" stop-color="#f08a1c"/><stop offset="1" stop-color="#d62b2b"/></linearGradient></defs>` +
      seg.map(g => `<rect x="${g[2]}" y="30" width="${g[3] - g[2]}" height="34" fill="${g[1]}" fill-opacity="${g[0] === 'Vis' ? 1 : .55}"/>` + sLab((g[2] + g[3]) / 2, 52, g[0], '#000')).join('') +
      `<g stroke="${MUT}"><line x1="168" y1="64" x2="20" y2="100"/><line x1="198" y1="64" x2="320" y2="100"/></g><rect x="20" y="100" width="300" height="22" fill="url(#sg)"/>` + sLab(42, 115, '400 nm', '#fff') + sLab(298, 115, '750 nm', '#fff') + sLab(170, 115, 'visible light', '#000') +
      `<text x="4" y="20" stroke="none" fill="${MUT}" font-size="10">long λ, low f</text><text x="336" y="20" text-anchor="end" stroke="none" fill="${MUT}" font-size="10">short λ, high f</text>` +
      sSub(170, 146, 'Radio ≥ 1 m · Microwave 1 mm–1 m · IR 700 nm–1 mm') + sSub(170, 160, 'UV 10–380 nm · X-ray 0.01–10 nm · gamma < 0.01 nm'); })()),
  'Electromagnetic spectrum (boundaries are conventional). Every band travels at the speed of light in vacuum.');
const FIG_SREFR = FIG(SV(340, 210, 'Light ray hitting a boundary between air and glass: incident ray, reflected ray and refracted ray bending toward the normal',
  `<rect x="10" y="100" width="320" height="100" fill="${MUT}" fill-opacity=".15" stroke="none"/><line x1="10" y1="100" x2="330" y2="100"/><line x1="170" y1="20" x2="170" y2="196" stroke-dasharray="4 4" stroke="${MUT}"/>` +
  `<line x1="110" y1="40" x2="170" y2="100" stroke="${ACC}" stroke-width="2.2"/><line x1="170" y1="100" x2="230" y2="40" stroke="${ACC2}" stroke-width="2"/><line x1="170" y1="100" x2="203" y2="162" stroke="${ACC}" stroke-width="2.2"/>` +
  `<path d="M170 76 A24 24 0 0 0 153 83" stroke="${MUT}"/>` + sLab(158, 68, 'θ₁') + `<path d="M170 128 A28 28 0 0 0 180 126" stroke="${MUT}"/>` + sLab(160, 142, 'θ₂') +
  sLab(84, 36, 'incident', ACC) + sLab(256, 36, 'reflected', ACC2) + sLab(246, 160, 'refracted', ACC) + sLab(40, 92, 'air n₁ = 1.00', MUT).replace('x="40"', 'x="62"') + sLab(62, 120, 'glass n₂ ≈ 1.5', MUT) + sLab(170, 14, 'normal', MUT) + sSub(170, 204, 'n₁ sinθ₁ = n₂ sinθ₂')),
  'Refraction (Snell’s law): light bends toward the normal when entering a slower (higher-index) medium.');
const sPhase = (cx, cy, r, a) => { const wan = a > Math.PI, al = wan ? 2 * Math.PI - a : a, c = Math.cos(al), rx = Math.abs(c) * r, sw = c > 0 ? 0 : 1; const lit = al < 0.02 ? '' : `<path d="M${cx} ${cy - r} A${r} ${r} 0 0 1 ${cx} ${cy + r} A${rx.toFixed(2)} ${r} 0 0 ${sw} ${cx} ${cy - r} Z" fill="#f2e6a8" stroke="none"${wan ? ` transform="translate(${2 * cx} 0) scale(-1 1)"` : ''}/>`; return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${MUT}" fill-opacity=".45"/>` + lit + `<circle cx="${cx}" cy="${cy}" r="${r}"/>`; };
const FIG_SMOON = FIG(SV(340, 220, 'Eight phases of the Moon over a 29.5-day cycle: new, waxing crescent, first quarter, waxing gibbous, full, waning gibbous, last quarter, waning crescent',
  ['New', 'Waxing crescent', 'First quarter', 'Waxing gibbous', 'Full', 'Waning gibbous', 'Last quarter', 'Waning crescent'].map((n, i) => { const cx = 42 + (i % 4) * 85, cy = 36 + Math.floor(i / 4) * 100; return sPhase(cx, cy, 24, i * Math.PI / 4) + sLab(cx, cy + 42, n.replace('Waxing crescent','Wax cresc').replace('Waxing gibbous','Wax gibb').replace('Waning gibbous','Wan gibb').replace('Waning crescent','Wan cresc').replace('First quarter','1st quarter').replace('Last quarter','3rd quarter')) + sSub(cx, cy + 54, 'day ' + (i * 3.69).toFixed(1)); }).join('')),
  'Phases as seen from the Northern Hemisphere (lit side shown yellow). Synodic month ≈ 29.53 days.');
const FIG_SENERGY = FIG(SV(340, 190, 'Energy flow from fuel to useful work through a power plant, transmission lines and an electric motor, with the remainder lost as heat',
  (() => { const k = 2.9, rows = [['Fuel energy in', 100, 0], ['Electricity from plant', 38, 62], ['Delivered to user', 36, 2], ['Useful motor work', 32, 4]];
    return rows.map((r, i) => { const y = 8 + i * 42, w = r[1] * k, lw = r[2] * k; return `<text x="10" y="${y + 10}" stroke="none" fill="currentColor" font-size="11">${r[0]}: ${r[1]}</text><rect x="10" y="${y + 15}" width="${w}" height="18" fill="var(--panel)" stroke="${ACC}" stroke-width="1.8"/>` + (lw ? `<rect x="${10 + w}" y="${y + 15}" width="${lw}" height="18" fill="${ACC2}" fill-opacity=".25" stroke-dasharray="3 3"/><text x="${lw > 40 ? 10 + w + lw / 2 : 10 + w + lw + 4}" y="${y + 28}" text-anchor="${lw > 40 ? 'middle' : 'start'}" stroke="none" fill="${ACC2}" font-size="10">−${r[2]} heat</text>` : ''); }).join('') + sSub(170, 184, 'illustrative: usable energy shrinks at each step'); })()),
  'Every energy conversion leaves some energy as low-grade heat. Overall efficiency = useful output ÷ input (here 32%).');
/* ===== Geology: data, diagrams and calculators (additive) ===== */
// name, formula, Mohs lo, hi, SG lo, hi, luster, streak, cleavage/clue, class
const GEO_MIN = [
['Quartz', 'SiO₂', 7, 7, 2.65, 2.65, 'glassy', 'white', 'no cleavage, conchoidal fracture; hexagonal crystals', 'Silicate'],
['K-feldspar (orthoclase)', 'KAlSi₃O₈', 6, 6, 2.55, 2.63, 'glassy', 'white', '2 cleavages at 90°; pink, cream or white', 'Silicate'],
['Plagioclase', '(Na,Ca)Al(Al,Si)Si₂O₈', 6, 6.5, 2.62, 2.76, 'glassy', 'white', '2 cleavages ≈ 86°; fine striations on one face', 'Silicate'],
['Muscovite mica', 'KAl₂(AlSi₃O₁₀)(OH)₂', 2, 2.5, 2.76, 3.0, 'pearly', 'white', '1 perfect cleavage; thin clear flexible sheets', 'Silicate'],
['Biotite mica', 'K(Mg,Fe)₃AlSi₃O₁₀(OH)₂', 2.5, 3, 2.7, 3.4, 'glassy-pearly', 'white-grey', '1 perfect cleavage; black-brown sheets', 'Silicate'],
['Hornblende', 'Ca₂(Mg,Fe,Al)₅(Si,Al)₈O₂₂(OH)₂', 5, 6, 3.0, 3.5, 'glassy', 'white-grey', '2 cleavages at 56°/124°; dark, elongated', 'Silicate'],
['Augite (pyroxene)', '(Ca,Mg,Fe)₂Si₂O₆', 5, 6, 3.2, 3.6, 'glassy', 'white-grey', '2 cleavages ≈ 90°; dark, stubby', 'Silicate'],
['Olivine', '(Mg,Fe)₂SiO₄', 6.5, 7, 3.2, 4.4, 'glassy', 'white', 'no cleavage; olive-green grains', 'Silicate'],
['Garnet', 'X₃Y₂(SiO₄)₃', 6.5, 7.5, 3.5, 4.3, 'glassy', 'white', 'no cleavage; dodecahedral crystals, red-brown', 'Silicate'],
['Topaz', 'Al₂SiO₄(F,OH)₂', 8, 8, 3.4, 3.6, 'glassy', 'white', '1 perfect cleavage; hard', 'Silicate'],
['Beryl', 'Be₃Al₂Si₆O₁₈', 7.5, 8, 2.6, 2.9, 'glassy', 'white', 'poor cleavage; hexagonal prisms', 'Silicate'],
['Tourmaline', 'complex borosilicate', 7, 7.5, 3.0, 3.3, 'glassy', 'white', 'no cleavage; striated, rounded-triangular prisms', 'Silicate'],
['Epidote', 'Ca₂(Al,Fe)₃Si₃O₁₂(OH)', 6, 7, 3.3, 3.5, 'glassy', 'white-grey', '1 good cleavage; pistachio green', 'Silicate'],
['Kyanite', 'Al₂SiO₅', 4.5, 7, 3.6, 3.7, 'glassy-pearly', 'white', 'blue blades; hardness differs by direction', 'Silicate'],
['Andalusite', 'Al₂SiO₅', 6.5, 7.5, 3.1, 3.2, 'glassy', 'white', 'square prisms; cross-shaped inclusions (chiastolite)', 'Silicate'],
['Staurolite', 'Fe₂Al₉Si₄O₂₃(OH)', 7, 7.5, 3.7, 3.8, 'glassy-dull', 'white-grey', 'brown cross-shaped twins', 'Silicate'],
['Talc', 'Mg₃Si₄O₁₀(OH)₂', 1, 1, 2.7, 2.8, 'pearly-greasy', 'white', 'soapy feel; 1 cleavage', 'Silicate'],
['Kaolinite (clay)', 'Al₂Si₂O₅(OH)₄', 2, 2.5, 2.6, 2.6, 'earthy', 'white', 'soft, earthy; clay smell when wet', 'Silicate'],
['Chlorite', '(Mg,Fe)₃(Si,Al)₄O₁₀(OH)₂·…', 2, 2.5, 2.6, 3.3, 'pearly-dull', 'pale green', '1 cleavage; green flexible but not elastic flakes', 'Silicate'],
['Serpentine', 'Mg₃Si₂O₅(OH)₄', 2.5, 5.5, 2.5, 2.6, 'waxy-silky', 'white', 'green, slippery, may be fibrous', 'Silicate'],
['Calcite', 'CaCO₃', 3, 3, 2.71, 2.71, 'glassy', 'white', '3 cleavages not at 90° (rhombs); fizzes in cold dilute HCl', 'Carbonate'],
['Dolomite', 'CaMg(CO₃)₂', 3.5, 4, 2.85, 2.85, 'glassy-pearly', 'white', 'rhombic; fizzes weakly unless powdered', 'Carbonate'],
['Malachite', 'Cu₂CO₃(OH)₂', 3.5, 4, 3.6, 4.0, 'silky-dull', 'light green', 'banded green; fizzes in acid', 'Carbonate'],
['Azurite', 'Cu₃(CO₃)₂(OH)₂', 3.5, 4, 3.7, 3.8, 'glassy', 'pale blue', 'deep azure blue; fizzes in acid', 'Carbonate'],
['Gypsum', 'CaSO₄·2H₂O', 2, 2, 2.3, 2.3, 'glassy-silky', 'white', 'scratched by fingernail; 1 perfect cleavage', 'Sulfate'],
['Barite', 'BaSO₄', 3, 3.5, 4.3, 4.6, 'glassy', 'white', 'unusually heavy for a pale mineral; 3 cleavages', 'Sulfate'],
['Halite', 'NaCl', 2.5, 2.5, 2.16, 2.17, 'glassy', 'white', '3 cleavages at 90° (cubes); salty taste', 'Halide'],
['Fluorite', 'CaF₂', 4, 4, 3.0, 3.3, 'glassy', 'white', '4 octahedral cleavages; purple, green, yellow', 'Halide'],
['Apatite', 'Ca₅(PO₄)₃(F,Cl,OH)', 5, 5, 3.1, 3.2, 'glassy', 'white', 'poor cleavage; hexagonal prisms', 'Phosphate'],
['Corundum', 'Al₂O₃', 9, 9, 3.9, 4.1, 'glassy', 'white', 'no cleavage, parting; ruby (red), sapphire (other)', 'Oxide'],
['Magnetite', 'Fe₃O₄', 5.5, 6.5, 5.1, 5.2, 'metallic', 'black', 'strongly magnetic', 'Oxide'],
['Hematite', 'Fe₂O₃', 5, 6.5, 4.9, 5.3, 'metallic-earthy', 'red-brown', 'red-brown streak even when the specimen is steel grey', 'Oxide'],
['Goethite / limonite', 'FeO(OH)', 5, 5.5, 3.3, 4.3, 'dull-earthy', 'yellow-brown', 'rust-coloured, earthy; weathering product', 'Oxide'],
['Cassiterite', 'SnO₂', 6, 7, 6.8, 7.1, 'adamantine', 'white-brown', 'very dense; brown-black', 'Oxide'],
['Pyrite', 'FeS₂', 6, 6.5, 4.9, 5.2, 'metallic', 'greenish-black', 'brassy cubes with striations; “fool’s gold”', 'Sulfide'],
['Chalcopyrite', 'CuFeS₂', 3.5, 4, 4.1, 4.3, 'metallic', 'greenish-black', 'brassy, tarnishes iridescent; softer than pyrite', 'Sulfide'],
['Galena', 'PbS', 2.5, 2.5, 7.4, 7.6, 'metallic', 'lead-grey', '3 cleavages at 90°; very heavy', 'Sulfide'],
['Sphalerite', 'ZnS', 3.5, 4, 3.9, 4.1, 'resinous-adamantine', 'yellow-brown to white', '6 cleavage directions; brown-black', 'Sulfide'],
['Cinnabar', 'HgS', 2, 2.5, 8.0, 8.2, 'adamantine-dull', 'scarlet', 'red; very dense; toxic mercury ore', 'Sulfide'],
['Graphite', 'C', 1, 2, 2.1, 2.3, 'metallic-dull', 'black', 'writes on paper; greasy; 1 cleavage', 'Native'],
['Sulfur', 'S', 1.5, 2.5, 2.0, 2.1, 'resinous', 'pale yellow', 'yellow; brittle; burns with blue flame', 'Native'],
['Native copper', 'Cu', 2.5, 3, 8.9, 8.9, 'metallic', 'copper-red', 'malleable; green tarnish', 'Native'],
['Gold (native)', 'Au', 2.5, 3, 15.5, 19.3, 'metallic', 'golden-yellow', 'malleable, does not shatter; pure 19.3, natural alloys lower', 'Native'],
['Diamond', 'C', 10, 10, 3.5, 3.53, 'adamantine', 'colourless', '4 perfect cleavages; hardest natural mineral', 'Native']];
const GEO_MATCH = (h, sg) => GEO_MIN.filter(m => (h === '' || h == null || (h >= m[2] - 0.3 && h <= m[3] + 0.3)) && (sg === '' || sg == null || (sg >= m[4] * 0.97 && sg <= m[5] * 1.03)));
const geoAz = (x, y) => { let a = Math.atan2(x, y) * 180 / Math.PI; return (a + 360) % 360; };
const geoBox = (x, y, w, h, t, c) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="var(--panel)" stroke="${c || 'currentColor'}"/>` + sLab(x + w / 2, y + h / 2 + 4, t);
const geoArr = (id, x1, y1, x2, y2, d) => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${ACC}" marker-end="url(#${id})"${d ? ' stroke-dasharray="4 3"' : ''}/>`;
const geoDef = id => `<defs><marker id="${id}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10z" fill="${ACC}" stroke="none"/></marker></defs>`;
const FIG_GROCK = FIG(SV(340, 250, 'Rock cycle: magma cools to igneous rock, weathering makes sediment, burial makes sedimentary rock, heat and pressure make metamorphic rock, melting returns to magma',
  geoDef('gra') + geoBox(120, 6, 100, 30, 'Magma') + geoBox(6, 92, 100, 30, 'Igneous') + geoBox(234, 92, 100, 30, 'Sediment') + geoBox(6, 190, 100, 30, 'Metamorphic') + geoBox(234, 190, 100, 30, 'Sedimentary') +
  geoArr('gra', 110, 36, 70, 90) + sSub(62, 66, 'cooling') + geoArr('gra', 108, 107, 232, 107) + sSub(170, 100, 'weathering,') + sSub(170, 124, 'erosion') +
  geoArr('gra', 284, 124, 284, 188) + sSub(318, 154, 'burial,') + sSub(318, 166, 'cement') +
  geoArr('gra', 232, 205, 108, 205) + sSub(170, 198, 'heat + pressure') + geoArr('gra', 56, 124, 56, 188) + sSub(56, 160, 'heat +') + sSub(56, 172, 'pressure') +
  geoArr('gra', 56, 188, 130, 38, 1).replace('56" y1="188"', '90" y1="188"') + sSub(130, 152, 'melting') +
  sSub(170, 244, 'uplift and erosion expose any rock to weathering')),
  'The rock cycle has no fixed order: any rock can move to any other state. The dashed arrow shows melting (any rock can melt).');
const FIG_GTIME = FIG(SV(340, 210, 'Earth history on a proportional bar from 4540 million years ago to today, with the Phanerozoic zoomed in to show Paleozoic, Mesozoic and Cenozoic',
  (() => { const k = 320 / 4540, sg = (a, b, n, c, x0, kk, y) => `<rect x="${x0 + (4540 - a) * kk}" y="${y}" width="${(a - b) * kk}" height="30" fill="${c}" fill-opacity=".5"/>`;
    const e = [['Hadean', 4540, 4000, '#a55'], ['Archean', 4000, 2500, '#a85'], ['Proterozoic', 2500, 538.8, '#8a6'], ['Ph', 538.8, 0, '#58a']];
    let s = '<text x="10" y="14" stroke="none" fill="currentColor" font-size="11">All Earth history (Ma = millions of years ago)</text>';
    e.forEach(g => s += `<rect x="${10 + (4540 - g[1]) * k}" y="22" width="${(g[1] - g[2]) * k}" height="30" fill="${g[3]}" fill-opacity=".55" stroke="currentColor"/>`);
    s += sLab(10 + 270 * k + 0, 42, 'Hadean').replace('text-anchor="middle"', 'text-anchor="middle" font-size="9"').replace('x="10"', 'x="28"');
    s += sLab(10 + (540 + 750) * k, 42, 'Archean') + sLab(10 + (1540 + 1000 + 700) * k - 40, 42, 'Proterozoic').replace('text-anchor="middle"', 'text-anchor="middle"');
    s += `<g stroke="${MUT}"><line x1="${10 + (4540 - 538.8) * k}" y1="52" x2="10" y2="86"/><line x1="330" y1="52" x2="330" y2="86"/></g>`;
    const k2 = 320 / 538.8, z = [['Paleozoic', 538.8, 251.9, '#8a6'], ['Mesozoic', 251.9, 66, '#c84'], ['Cenozoic', 66, 0, '#58a']];
    z.forEach(g => { const x = 10 + (538.8 - g[1]) * k2, w = (g[1] - g[2]) * k2; s += `<rect x="${x}" y="86" width="${w}" height="30" fill="${g[3]}" fill-opacity=".55" stroke="currentColor"/>` + sLab(x + w / 2, 105, w < 60 ? 'Cz' : g[0]); });
    [445, 372, 252, 201, 66].forEach(m => s += `<line x1="${10 + (538.8 - m) * k2}" y1="116" x2="${10 + (538.8 - m) * k2}" y2="128" stroke="${ACC}" stroke-width="2"/>`);
    s += sLab(170, 146, 'red ticks: the “Big Five” mass extinctions', ACC) + sSub(170, 160, '≈ 445 · 372 · 252 · 201 · 66 Ma');
    s += `<text x="10" y="184" stroke="none" fill="currentColor" font-size="10">538.8 Ma</text><text x="330" y="184" text-anchor="end" stroke="none" fill="currentColor" font-size="10">today</text>` + sSub(170, 200, 'Phanerozoic = only the last ≈ 12% of Earth history');
    return s; })()),
  'Top: all of Earth history (proportional). Bottom: the last 538.8 million years enlarged. Boundary dates are approximate.');
const FIG_GFAULT = FIG(SV(340, 190, 'Three fault types: normal fault where the hanging wall moves down, reverse fault where it moves up, and strike-slip fault with sideways motion',
  (() => { const ln = (d) => [25, 40, 55].map(y => `<line x1="5" y1="${y}" x2="${35 + (y - 10) * .5}" y2="${y}" stroke="${MUT}"/><line x1="${35 + (y - 10) * .5}" y1="${y + d}" x2="105" y2="${y + d}" stroke="${MUT}"/>`).join('');
    const blk = (i, d, t1, t2) => `<g transform="translate(${i * 112 + 2} 24)"><polygon points="5,10 35,10 65,70 5,70" fill="var(--panel)"/><polygon points="35,10 105,10 105,70 65,70" fill="var(--panel)"/>${ln(d)}<line x1="35" y1="10" x2="65" y2="70" stroke="${ACC}" stroke-width="2.2"/><rect x="5" y="10" width="100" height="60" stroke="currentColor"/>` + `<path d="M${d > 0 ? 88 : 88} ${d > 0 ? 24 : 44} l0 ${d > 0 ? 16 : -16}" stroke="${ACC2}" marker-end="url(#gfa)"/>` + `</g>` + sLab(i * 112 + 58, 18, t1) + sSub(i * 112 + 58, 114, t2);
    const sl = `<g transform="translate(${2 * 112 + 2} 24)"><rect x="5" y="10" width="100" height="60" fill="var(--panel)" stroke="currentColor"/><line x1="55" y1="10" x2="55" y2="70" stroke="${ACC}" stroke-width="2.2"/><path d="M5 30 H55 L55 40 H105" stroke="${MUT}" stroke-width="2.5"/><path d="M25 52 h18" stroke="${ACC2}" marker-end="url(#gfa)"/><path d="M85 28 h-18" stroke="${ACC2}" marker-end="url(#gfa)"/></g>` + sLab(2 * 112 + 58, 18, 'Strike-slip') + sSub(2 * 112 + 58, 114, 'sideways, plan view');
    return geoDef('gfa').replace('id="gfa"', 'id="gfa"') + blk(0, 12, 'Normal', 'extension') + blk(1, -12, 'Reverse', 'compression') + sl + sSub(170, 140, 'red = fault; grey = offset layers') + sSub(170, 156, 'hanging wall = block above fault plane') + sSub(170, 170, 'footwall = block below it'); })()),
  'Normal faults lengthen the crust, reverse and thrust faults shorten it, strike-slip faults slide past each other.');
const FIG_GFOLD = FIG(SV(340, 196, 'Cross-section of folded rock layers showing an anticline arching up and a syncline sagging down',
  (() => { let s = ''; for (let L = 0; L < 4; L++) { const pts = Array.from({ length: 65 }, (_, i) => { const x = 10 + i * 5, y = 70 + L * 16 - 28 * Math.sin((i / 64) * 2 * Math.PI * 1.0 - 0.0); return x + ',' + y.toFixed(1); }); s += `<polyline points="${pts.join(' ')}" stroke="${L % 2 ? ACC2 : ACC}" stroke-width="3"/>`; }
    s += sLab(85, 24, 'anticline') + sSub(85, 36, 'older rock in core') + sLab(250, 168, 'syncline') + sSub(250, 180, 'younger rock in core') + `<line x1="10" y1="70" x2="330" y2="70" stroke="${MUT}" stroke-dasharray="3 4"/>` + sSub(120, 192, 'axial plane passes through each hinge'); return s; })()),
  'Anticline: layers dip away from the crest. Syncline: layers dip toward the trough. Which is “older in the core” holds when the layers are right-way-up.');
const FIG_GSTRIKE = FIG(SV(340, 190, 'Strike and dip: on a map the strike line is drawn with a short tick for dip direction; in cross-section dip is the angle below horizontal',
  `<rect x="10" y="20" width="150" height="130" stroke="${MUT}"/><line x1="30" y1="110" x2="140" y2="50" stroke="currentColor" stroke-width="2.2"/><line x1="85" y1="80" x2="107" y2="118" stroke="currentColor" stroke-width="2.2"/><text x="112" y="132" stroke="none" fill="currentColor" font-size="12">35</text><path d="M30 110 L140 50" stroke="none"/>` +
  sLab(85, 40, 'MAP VIEW') + sSub(85, 162, 'line = strike') + sSub(85, 176, 'tick = dip direction') +
  `<line x1="180" y1="70" x2="330" y2="70" stroke="${MUT}" stroke-dasharray="4 4"/><line x1="190" y1="50" x2="320" y2="125" stroke="${ACC}" stroke-width="2.4"/><path d="M262 125 A56 56 0 0 0 270 98" stroke="none"/><path d="M240 70 A44 44 0 0 1 228 98" stroke="${MUT}" fill="none"/>` +
  sLab(255, 40, 'CROSS-SECTION') + sLab(296, 90, 'dip δ', ACC2) + sSub(255, 162, 'dip = angle below') + sSub(255, 176, 'horizontal')),
  'Strike = compass direction of the horizontal line on a bedding or fault plane. Dip = steepest angle downward from horizontal. Right-hand rule: dip is to your right as you face along the strike.');
const FIG_GSOIL = FIG(SV(340, 210, 'Soil profile showing horizons O, A, E, B, C and bedrock R from surface downward',
  (() => { const h = [['O', 'organic litter', 18, '#6a4'], ['A', 'topsoil, humus-rich', 30, '#654'], ['E', 'leached, pale (not always present)', 24, '#cba'], ['B', 'subsoil: clay, iron accumulates', 36, '#a74'], ['C', 'weathered parent material', 36, '#b96'], ['R', 'unweathered bedrock', 32, '#888']];
    let y = 10, s = ''; h.forEach(r => { s += `<rect x="10" y="${y}" width="76" height="${r[2]}" fill="${r[3]}" fill-opacity=".6" stroke="currentColor"/>` + sLab(48, y + r[2] / 2 + 4, r[0]) + `<text x="94" y="${y + r[2] / 2 + 4}" stroke="none" fill="currentColor" font-size="11">${r[1]}</text>`; y += r[2]; });
    return s + sSub(170, 200, 'A + E + B together form the solum (true soil)'); })()),
  'Typical soil horizons. Thickness varies from a few cm to several metres; not every profile has every horizon.');
const FIG_GMOHS = FIG(SV(340, 210, 'Bar chart of absolute hardness of the ten Mohs minerals showing that the scale is not linear',
  (() => { const d = [['1 Talc', 1], ['2 Gypsum', 2], ['3 Calcite', 9], ['4 Fluorite', 21], ['5 Apatite', 48], ['6 Orthoclase', 72], ['7 Quartz', 100], ['8 Topaz', 200], ['9 Corundum', 400], ['10 Diamond', 1500]];
    return d.map((r, i) => { const y = 8 + i * 17, w = Math.max(2, r[1] / 1500 * 190); return `<text x="10" y="${y + 11}" stroke="none" fill="currentColor" font-size="11">${r[0]}</text><rect x="108" y="${y}" width="${w}" height="13" fill="${ACC}" fill-opacity=".6" stroke="${ACC}"/><text x="${112 + w}" y="${y + 11}" stroke="none" fill="currentColor" font-size="10">${r[1]}</text>`; }).join('') + sSub(170, 196, 'relative scratch hardness (sclerometer)'); })()),
  'Mohs numbers rank minerals; they are not evenly spaced. Diamond is far harder than its step from 9 to 10 suggests (≈ 4× corundum).');
const FIG_GGRAIN = FIG(SV(340, 110, 'Wentworth grain size scale from clay to boulder on a logarithmic bar',
  (() => { const u = 16, b = [['clay', 10, 8, '#a8a'], ['silt', 8, 4, '#b95'], ['sand', 4, -1, '#dc7'], ['', -1, -2, '#aa7'], ['pebble', -2, -6, '#8a8'], ['cobble', -6, -8, '#79a'], ['boulder', -8, -10, '#888']];
    return b.map(g => { const x = 10 + (10 - g[1]) * u, w = (g[1] - g[2]) * u; return `<rect x="${x}" y="30" width="${w}" height="26" fill="${g[3]}" fill-opacity=".6" stroke="currentColor"/>` + (g[0] ? sLab(x + w / 2, 47, g[0].length * 6.6 > w ? g[0].slice(0, 3) : g[0]) : ''); }).join('') +
      [[8, '1/256'], [4, '1/16'], [-1, '2'], [-2, '4'], [-6, '64'], [-8, '256']].map((t, i) => `<line x1="${10 + (10 - t[0]) * u}" y1="56" x2="${10 + (10 - t[0]) * u}" y2="${62 + (i % 2) * 12}" stroke="${MUT}"/>` + sSub(10 + (10 - t[0]) * u, 72 + (i % 2) * 12, t[1])).join('') + sSub(170, 20, 'grain diameter in mm (log scale, each unit = ×2)') + sSub(170, 106, 'boundaries: 1/256, 1/16, 2, 4, 64, 256 mm'); })()),
  'Wentworth scale: clay < 1/256 mm, silt up to 1/16, sand up to 2, granule up to 4, pebble up to 64, cobble up to 256, boulder above.');

calc({ id: 'geo-sg', title: 'Specific gravity and density by weighing in water', desc: 'Hydrostatic method: weigh the specimen in air, then hung in water. SG = W_air ÷ (W_air − W_water). Any unit of weight works if both use the same one.', kw: ['specific gravity', 'mineral density', 'hydrostatic weighing', 'density of rock', 'SG of mineral'],
  fields: [F('wa', 'Weight in air', 54.0, 'g'), F('ww', 'Weight suspended in water', 33.9, 'g'), F('tw', 'Water density', 0.9982, 'g/cm³')],
  run: v => { if (v.wa <= 0 || v.ww < 0 || v.ww >= v.wa) return { err: 'Weight in water must be less than weight in air (and ≥ 0).' }; const sg = v.wa / (v.wa - v.ww), d = sg * v.tw, m = GEO_MATCH('', sg).map(x => x[0]); return [['Specific gravity', sg], ['Density', d, 'g/cm³'], ['Density', d * 1000, 'kg/m³'], ['Density', d * 62.428, 'lb/ft³'], ['Volume', (v.wa - v.ww) / v.tw, 'cm³'], 'Candidate minerals by SG: ' + (m.length ? m.slice(0, 10).join(', ') : 'none in table')]; } });
calc({ id: 'geo-minfind', title: 'Mineral finder by hardness and specific gravity', desc: 'Fill in one or both. Matches use a ±0.3 hardness and ±3% SG tolerance and cover only the common minerals in the table above.', kw: ['identify mineral', 'mineral key', 'hardness and density', 'what mineral is this'],
  fields: [F('h', 'Mohs hardness', 6.5, '', { opt: 1 }), F('sg', 'Specific gravity', 5.0, '', { opt: 1 })],
  run: v => { const m = GEO_MATCH(v.h, v.sg); if (v.h === '' && v.sg === '') return { err: 'Enter hardness, specific gravity, or both.' }; return [['Matches', m.length]].concat(m.slice(0, 12).map(x => [x[0], 'H ' + x[2] + (x[3] > x[2] ? '–' + x[3] : '') + ' · SG ' + x[4] + (x[5] > x[4] ? '–' + x[5] : '') + ' · ' + x[6] + ' · streak ' + x[7]])); } });
calc({ id: 'geo-soil', title: 'Soil phase relationships (unit weights, porosity, saturation)', desc: 'From specific gravity of solids Gs, void ratio e and water content w. γw = 62.4 lb/ft³ = 9.81 kN/m³.', kw: ['void ratio', 'porosity', 'dry unit weight', 'degree of saturation', 'soil density', 'saturated unit weight'],
  fields: [F('gs', 'Specific gravity of solids Gs', 2.65), F('e', 'Void ratio e', 0.6), F('w', 'Water content w', 15, '%')],
  run: v => { if (v.gs <= 0 || v.e <= 0 || v.w < 0) return { err: 'Gs and e must be above 0; w cannot be negative.' }; const S = v.w / 100 * v.gs / v.e; if (S > 1.0001) return { err: 'w × Gs ÷ e exceeds 100% saturation: the inputs are not consistent. Lower w or raise e.' }; const n = v.e / (1 + v.e), gd = v.gs * 62.4 / (1 + v.e), gm = gd * (1 + v.w / 100), gsat = (v.gs + v.e) * 62.4 / (1 + v.e); return [['Porosity n', n * 100, '%'], ['Degree of saturation S', S * 100, '%'], ['Dry unit weight', gd, 'lb/ft³'], ['Moist unit weight', gm, 'lb/ft³'], ['Saturated unit weight', gsat, 'lb/ft³'], ['Buoyant unit weight', gsat - 62.4, 'lb/ft³'], ['Dry unit weight', gd * 0.157087, 'kN/m³'], ['Dry density', gd * 16.0185, 'kg/m³']]; } });
calc({ id: 'geo-atterberg', title: 'Atterberg limits: plasticity index and consistency', desc: 'LL liquid limit, PL plastic limit, w natural water content (all %). Rough classification only; confirm in a lab.', kw: ['liquid limit', 'plastic limit', 'plasticity index', 'liquidity index', 'A-line', 'clay plasticity'],
  fields: [F('ll', 'Liquid limit LL', 48, '%'), F('pl', 'Plastic limit PL', 22, '%'), F('w', 'Natural water content (optional)', 30, '%', { opt: 1 })],
  run: v => { if (v.ll <= v.pl) return { err: 'LL must exceed PL.' }; const pi = v.ll - v.pl, a = 0.73 * (v.ll - 20), pcl = pi < 4 ? 'plasticity too low for clay behaviour (silt-like)' : pi < 7 ? 'slightly plastic' : pi < 17 ? 'medium plasticity' : 'high plasticity'; const o = [['Plasticity index PI', pi, '%'], ['PI of A-line at this LL', Math.max(0, a), '%'], ['Plasticity', pcl], ['Group tendency', (pi >= a && pi >= 4 ? 'clay (C)' : 'silt or organic (M/O)') + (v.ll >= 50 ? ', high LL (H)' : ', low LL (L)')]]; if (v.w !== '' && v.w != null) { const li = (v.w - v.pl) / pi; o.push(['Liquidity index LI', li]); o.push(['State', li < 0 ? 'brittle solid (below PL)' : li <= 1 ? 'plastic' : 'viscous liquid (above LL)']); } return o; } });
calc({ id: 'geo-texture', title: 'Soil texture class from sand, silt and clay (USDA)', desc: 'Percent by weight of the fine-earth fraction (particles < 2 mm). Should total ≈ 100. Class boundaries are approximate.', kw: ['soil texture', 'sand silt clay', 'loam', 'texture triangle', 'soil classification'],
  fields: [F('sa', 'Sand (0.05–2 mm)', 40, '%'), F('si', 'Silt (0.002–0.05 mm)', 40, '%'), F('cl', 'Clay (< 0.002 mm)', 20, '%')],
  run: v => { const t = v.sa + v.si + v.cl; if (v.sa < 0 || v.si < 0 || v.cl < 0 || Math.abs(t - 100) > 3) return { err: 'Percentages must be ≥ 0 and total about 100 (now ' + t + ').' }; const f = 100 / t, S = v.sa * f, Z = v.si * f, C = v.cl * f; let c; if (Z + 1.5 * C < 15) c = 'Sand'; else if (Z + 1.5 * C >= 15 && Z + 2 * C < 30) c = 'Loamy sand'; else if ((C >= 7 && C < 20 && S > 52 && Z + 2 * C >= 30) || (C < 7 && Z < 50 && Z + 2 * C >= 30)) c = 'Sandy loam'; else if (C >= 7 && C < 27 && Z >= 28 && Z < 50 && S <= 52) c = 'Loam'; else if ((Z >= 50 && C >= 12 && C < 27) || (Z >= 50 && Z < 80 && C < 12)) c = 'Silt loam'; else if (Z >= 80 && C < 12) c = 'Silt'; else if (C >= 20 && C < 35 && Z < 28 && S > 45) c = 'Sandy clay loam'; else if (C >= 27 && C < 40 && S > 20 && S <= 45) c = 'Clay loam'; else if (C >= 27 && C < 40 && S <= 20) c = 'Silty clay loam'; else if (C >= 35 && S > 45) c = 'Sandy clay'; else if (C >= 40 && Z >= 40) c = 'Silty clay'; else if (C >= 40 && S <= 45 && Z < 40) c = 'Clay'; else c = 'On a boundary; check inputs'; return [['Texture class', c], ['Normalised sand / silt / clay', S.toFixed(1) + ' / ' + Z.toFixed(1) + ' / ' + C.toFixed(1) + ' %']]; } });
calc({ id: 'geo-grain', title: 'Grain size class (Wentworth) and phi value', desc: 'Particle diameter in mm. φ = −log₂(d in mm).', kw: ['grain size', 'Wentworth', 'sand or silt', 'phi scale', 'particle size', 'clast size'],
  fields: [F('d', 'Grain diameter', 0.25, 'mm')],
  run: v => { if (v.d <= 0) return { err: 'Diameter must be above 0.' }; const d = v.d; const c = d < 1 / 256 ? 'Clay' : d < 1 / 16 ? 'Silt' : d < 0.125 ? 'Very fine sand' : d < 0.25 ? 'Fine sand' : d < 0.5 ? 'Medium sand' : d < 1 ? 'Coarse sand' : d < 2 ? 'Very coarse sand' : d < 4 ? 'Granule' : d < 64 ? 'Pebble' : d < 256 ? 'Cobble' : 'Boulder'; return [['Class', c], ['φ (phi)', -Math.log2(d)], ['Diameter', d * 1000, 'µm'], ['Diameter', d / 25.4, 'in']]; } });
calc({ id: 'geo-dipapp', title: 'True and apparent dip', desc: 'Apparent dip is the dip seen in a cut that is not perpendicular to strike. β = angle between strike and the cut direction (0–90°). tan(apparent) = tan(true) × sin β.', kw: ['apparent dip', 'true dip', 'cross-section dip', 'strike dip conversion'],
  fields: [SEL('m', 'Known value', [[1, 'True dip (find apparent)'], [2, 'Apparent dip (find true)']], 1), F('d', 'Dip', 40, '°'), F('b', 'β: angle from strike to section line', 30, '°')],
  run: v => { if (v.d <= 0 || v.d >= 90 || v.b <= 0 || v.b > 90) return { err: 'Dip must be 0–90° (exclusive); β must be 0–90°.' }; const t = Math.tan(v.d * D2R); if (+v.m === 1) return [['Apparent dip', Math.atan(t * Math.sin(v.b * D2R)) * R2D, '°']]; const x = t / Math.sin(v.b * D2R); return [['True dip', Math.atan(x) * R2D, '°']]; } });
calc({ id: 'geo-thick', title: 'Bed thickness from outcrop width', desc: 'For flat ground. Width measured along a line at angle β to strike (90° = straight across strike). Corrections are needed on sloping ground.', kw: ['true thickness', 'outcrop width', 'bed thickness', 'stratigraphic thickness'],
  fields: [F('w', 'Outcrop width on the ground', 120, 'm'), F('d', 'Dip of bed', 30, '°'), F('b', 'β: angle between strike and measurement line', 90, '°')],
  run: v => { if (v.w <= 0 || v.d <= 0 || v.d > 90 || v.b <= 0 || v.b > 90) return { err: 'Width above 0; dip and β in (0, 90].' }; const wp = v.w * Math.sin(v.b * D2R); return [['Width across strike', wp, 'm'], ['True (perpendicular) thickness', wp * Math.sin(v.d * D2R), 'm'], ['Vertical thickness', wp * Math.tan(v.d * D2R), 'm']]; } });
calc({ id: 'geo-3pt', title: 'Three-point problem: strike and dip of a plane', desc: 'Three points on one surface (x east, y north, z elevation, same units). Returns strike by the right-hand rule, dip and dip direction.', kw: ['three point problem', 'strike and dip from points', 'plane orientation', 'bedding attitude'],
  fields: [F('x1', 'Point 1 x', 0), F('y1', 'Point 1 y', 0), F('z1', 'Point 1 z', 100), F('x2', 'Point 2 x', 100), F('y2', 'Point 2 y', 0), F('z2', 'Point 2 z', 100), F('x3', 'Point 3 x', 0), F('y3', 'Point 3 y', 100), F('z3', 'Point 3 z', 50)],
  run: v => { const a = [v.x2 - v.x1, v.y2 - v.y1, v.z2 - v.z1], b = [v.x3 - v.x1, v.y3 - v.y1, v.z3 - v.z1]; let n = [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]; if (n[2] < 0) n = n.map(q => -q); if (n[2] === 0 && n[0] === 0 && n[1] === 0) return { err: 'Points are in a line; choose three non-collinear points.' }; const h = Math.hypot(n[0], n[1]); if (n[2] === 0) return { err: 'Plane is vertical; strike is along the line of points and dip is 90°.' }; const dip = Math.atan(h / n[2]) * R2D; if (h < 1e-12) return { err: 'Plane is horizontal (dip 0°).' }; const dd = geoAz(n[0], n[1]), st = (dd + 270) % 360; return [['Dip', dip, '°'], ['Dip direction', dd, '° azimuth'], ['Strike (right-hand rule)', st, '° azimuth'], ['Written as', Math.round(st) + '° / ' + Math.round(dip) + '° toward ' + Math.round(dd) + '°']]; } });
calc({ id: 'geo-bearing', title: 'True bearing to magnetic bearing (declination)', desc: 'Declination is east (+) or west (−). Magnetic = True − Declination. Look up current local declination with the NOAA or national geomagnetic calculator.', kw: ['magnetic declination', 'true north', 'compass bearing', 'azimuth conversion', 'quadrant bearing'],
  fields: [F('t', 'True azimuth', 45, '°'), F('dec', 'Declination (east +, west −)', -10, '°')],
  run: v => { const m = ((v.t - v.dec) % 360 + 360) % 360, q = a => { a = ((a % 360) + 360) % 360; return a <= 90 ? 'N ' + a.toFixed(1) + '° E' : a <= 180 ? 'S ' + (180 - a).toFixed(1) + '° E' : a <= 270 ? 'S ' + (a - 180).toFixed(1) + '° W' : 'N ' + (360 - a).toFixed(1) + '° W'; }; return [['Magnetic azimuth', m, '°'], ['True (quadrant form)', q(v.t)], ['Magnetic (quadrant form)', q(m)]]; } });
calc({ id: 'geo-mapscale', title: 'Map distance to ground distance', desc: 'Scale denominator for 1:24,000 is 24000.', kw: ['map scale', 'ground distance', 'representative fraction', 'quadrangle scale'],
  fields: [F('d', 'Distance on map', 5, ''), SEL('u', 'Map unit', [[1, 'cm'], [2.54, 'in'], [0.1, 'mm']], 1), F('s', 'Scale denominator', 24000)],
  run: v => { if (v.d < 0 || v.s <= 0) return { err: 'Enter positive values.' }; const cm = v.d * v.u * v.s, m = cm / 100; return [['Ground distance', m, 'm'], ['Ground distance', m / 1000, 'km'], ['Ground distance', m / 0.3048, 'ft'], ['Ground distance', m / 1609.344, 'mi']]; } });
calc({ id: 'geo-quakedist', title: 'Earthquake distance from S–P lag', desc: 'Rule of thumb for local earthquakes: distance ≈ 8 km per second of S–P interval. Real values vary with the crust; use it only for estimates.', kw: ['S-P interval', 'distance to earthquake', 'seismograph', 'P wave S wave', 'epicenter distance'],
  fields: [F('dt', 'S minus P arrival time', 12, 's')],
  run: v => { if (v.dt <= 0) return { err: 'The S–P time must be above 0.' }; const km = v.dt * 8; return [['Approx. distance', km, 'km'], ['Approx. distance', km / 1.609344, 'mi'], ['P wave travel time (≈ 6 km/s)', km / 6, 's'], ['S wave travel time (≈ 3.5 km/s)', km / 3.5, 's']]; } });
calc({ id: 'geo-plate', title: 'Plate motion and slow geological rates', desc: 'Convert a rate in mm/yr (= km per million years) into distance over a time span.', kw: ['plate speed', 'continental drift', 'cm per year', 'sea floor spreading', 'erosion rate', 'uplift rate'],
  fields: [F('r', 'Rate', 25, 'mm/yr'), F('t', 'Time', 10, 'million years')],
  run: v => { if (v.r < 0 || v.t < 0) return { err: 'Enter non-negative values.' }; const km = v.r * v.t; return [['Distance moved', km, 'km'], ['Distance moved', km / 1.609344, 'mi'], ['Rate', v.r / 10, 'cm/yr'], ['Rate', v.r / 25.4, 'in/yr'], ['Rate', v.r * 1e-3 / 3.15576e7 * 1e9, 'nm/s'], ['Time to move 1 m', 1000 / (v.r || NaN), 'years']]; } });
calc({ id: 'geo-sedrate', title: 'Sedimentation rate or depositional time', desc: 'Compacted thickness ÷ time. Older rock has been compressed, so the original sediment was thicker.', kw: ['sedimentation rate', 'deposition time', 'varves', 'accumulation rate', 'thickness per year'],
  fields: [F('h', 'Thickness', 30, 'm'), F('t', 'Time span', 1.5, 'million years')],
  run: v => { if (v.h < 0 || v.t <= 0) return { err: 'Thickness ≥ 0; time above 0.' }; const r = v.h / v.t; return [['Rate', r, 'm per million years'], ['Rate', r / 1000, 'mm/yr'], ['Rate', r / 10, 'cm per 10,000 yr'], ['Time per metre', 1e6 / r, 'years']]; } });
calc({ id: 'geo-clock', title: 'Earth history as a 24-hour clock', desc: 'Maps a date in millions of years ago onto a day running from Earth’s formation (4540 Ma, 00:00) to now (24:00).', kw: ['geologic clock', 'time scale analogy', 'deep time', 'Ma to clock time'],
  fields: [F('ma', 'Millions of years ago', 66, 'Ma')],
  run: v => { if (v.ma < 0 || v.ma > 4540) return { err: 'Enter 0–4540 Ma.' }; const s = (1 - v.ma / 4540) * 86400, h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), sec = Math.floor(s % 60), p = n => String(n).padStart(2, '0'); return [['Clock time', p(h) + ':' + p(m) + ':' + p(sec)], ['Seconds before midnight', 86400 - s, 's'], ['Fraction of Earth history elapsed', (1 - v.ma / 4540) * 100, '%']]; } });
/* ===== Glue, solvents, paints: data, diagrams, calculators (additive) ===== */
// name, MW, density g/mL, LEL %, OSHA PEL ppm (8 h TWA), flash point C (closed cup), boiling point C, evaporation class
