kk('thermo', 'R', 'Molar gas constant', 'R', kn(K_R), 'J/(mol·K)', `${kn(kLatm, 12)} L·atm/(mol·K); 8.314 462 618 L·kPa/(mol·K); ${kn(kRtorr, 10)} L·Torr/(mol·K); ${kn(K_R / 4.184, 10)} cal/(mol·K); ${kn(K_R * 453.59237 * 5 / 9 / 1055.05585262, 8)} BTU/(lbmol·°R)`, 'D', '', '', 'Gas constant in the ideal-gas law pV = nRT; R = N_A·k_B.', CDd);
kk('thermo', 'sigma', 'Stefan–Boltzmann constant', 'σ', kn(K_sigma), 'W/(m²·K⁴)', '5.670 374 × 10⁻⁸ W·m⁻²·K⁻⁴; 1.713 4 × 10⁻⁹ BTU/(h·ft²·°R⁴)', 'D', '', '', 'Power radiated per unit area of a black body, j = σT⁴; σ = 2π⁵k_B⁴/(15h³c²).', CDd);
kk('thermo,em', 'F', 'Faraday constant', 'F', kn(K_F), 'C/mol', '26.801 48 A·h/mol; N_A·e', 'D', '', '', 'Charge of one mole of elementary charges.', CDd);
kk('thermo', 'b_wien', 'Wien wavelength displacement constant', 'b', kn(K_h * K_c / (K_k * K_x5)), 'm·K', '2897.771 955 µm·K', 'D', '', '', 'Peak wavelength of black-body radiation, λ_max = b/T.', CDd);
kk('thermo', 'b_wien_nu', 'Wien frequency displacement constant', 'b′', kn(K_x3 * K_k / K_h), 'Hz/K', '5.879 × 10¹⁰ Hz/K', 'D', '', '', 'Peak frequency of black-body radiation per unit temperature, ν_max = b′·T.', CDd);
kk('thermo', 'c1', 'First radiation constant', 'c₁', kn(2 * Math.PI * K_h * K_c * K_c), 'W·m²', '2πhc²', 'D', '', '', 'Used in Planck’s law of black-body radiation.', CDd);
kk('thermo', 'c2', 'Second radiation constant', 'c₂', kn(K_h * K_c / K_k), 'm·K', '1.438 777 cm·K', 'D', '', '', 'hc/k_B; appears in the exponent of Planck’s law.', CDd);
kk('em', 'Phi0', 'Magnetic flux quantum', 'Φ₀', kn(K_h / (2 * K_e)), 'Wb', 'V·s; h/2e', 'D', '', '', 'Quantum of magnetic flux in a superconducting loop.', CDd);
kk('em', 'G0', 'Conductance quantum', 'G₀', kn(2 * K_e * K_e / K_h), 'S', '≈ 1/12 906.404 Ω; 2e²/h', 'D', '', '', 'Quantum of electrical conductance.', CDd);
kk('em', 'R_K', 'von Klitzing constant', 'R_K', kn(K_h / (K_e * K_e), 13), 'Ω', 'h/e²', 'D', '', '', 'Quantized Hall resistance, h/e²; the Ω is realized with the quantum Hall effect.', CDd);
kk('em', 'K_J', 'Josephson constant', 'K_J', kn(2 * K_e / K_h), 'Hz/V', '483 597.848 4 GHz/V; 2e/h', 'D', '', '', 'Frequency-to-voltage ratio of the Josephson effect; the volt is realized with it.', CDd);
kk('thermo', 'Vm_100', 'Molar volume of an ideal gas (273.15 K, 100 kPa)', 'V_m', kn(K_R * 273.15 / 100000), 'm³/mol', '22.710 954 64 L/mol', 'D', '', '', 'IUPAC STP: volume of one mole of ideal gas at 0 °C and 100 kPa.', CDd);
kk('thermo', 'Vm_atm', 'Molar volume of an ideal gas (273.15 K, 101.325 kPa)', 'V_m', kn(K_R * 273.15 / 101325), 'm³/mol', '22.413 969 54 L/mol', 'D', '', '', 'Volume of one mole of ideal gas at 0 °C and 1 atm.', CDd);
kk('thermo', 'Vm_satp', 'Molar volume of an ideal gas (298.15 K, 100 kPa)', 'V_m', kn(K_R * 298.15 / 100000), 'm³/mol', '24.789 570 L/mol', 'D', '', '', 'Volume of one mole of ideal gas at SATP (25 °C, 100 kPa).', CDd);
kk('thermo', 'n0', 'Loschmidt constant (273.15 K, 101.325 kPa)', 'n₀', kn(K_NA * 101325 / (K_R * 273.15)), 'm⁻³', '2.686 780 × 10¹⁹ cm⁻³', 'D', '', '', 'Number density of an ideal gas at 0 °C and 1 atm.', CDd);

