const cpCoreStr = z => { const cores = [[86, 'Rn', 18], [54, 'Xe', 14], [36, 'Kr', 9], [18, 'Ar', 5], [10, 'Ne', 3], [2, 'He', 1]]; for (const [cz, nm, cnt] of cores) { if (z > cz) { const occ = cpOcc(z, 0), coreOrbs = CP_ORB.slice(0, cnt).map(CP_NAME), rest = cpShown(occ).filter(o => !coreOrbs.includes(CP_NAME(o))); return '[' + nm + '] ' + rest.map(o => CP_NAME(o) + cpSup(occ[CP_NAME(o)])).join(' '); } } return cpConfigStr(z, 0); };

