const g1Parse = s => { const m = /^\s*(\d{4})-(\d{1,2})-(\d{1,2})\s*$/.exec(s || ''); if (!m) return null; const y = +m[1], mo = +m[2], d = +m[3], t = new Date(Date.UTC(y, mo - 1, d)); return t.getUTCFullYear() === y && t.getUTCMonth() === mo - 1 && t.getUTCDate() === d ? t : null; };
const G1DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
