calc({ id: 'g2-battery', title: 'Battery runtime estimate', desc: 'Stored energy (Wh) = volts × amp-hours; runtime = usable energy × efficiency ÷ load', kw: ['battery life', 'runtime', 'amp hours', 'watt hours', 'inverter', 'power bank'],
  fields: [F('v', 'Battery voltage', 12, 'V'), F('ah', 'Capacity', 100, 'Ah'), F('w', 'Load power', 150, 'W'), F('dod', 'Usable fraction of capacity', 80, '%'), F('eff', 'Conversion efficiency (inverter etc.)', 90, '%')],
  run: v => { if (v.w <= 0) return { err: 'Load must be above 0.' }; const wh = v.v * v.ah, use = wh * v.dod / 100 * v.eff / 100, h = use / v.w; return [['Stored energy', wh, 'Wh'], ['Deliverable energy', use, 'Wh'], ['Runtime', h, 'h'], ['Runtime', Math.floor(h) + ' h ' + Math.round((h % 1) * 60) + ' min'], ['Load current at battery', v.w / (v.v * v.eff / 100), 'A']]; } });
