calc({ id: 'mw-volume', title: 'Volume from weight or mass and density', desc: 'volume = mass ÷ density: how much space a given weight of material takes. Useful for liquids, aggregates and stock.', kw: ['volume from weight', 'gallons from pounds', 'volume of liquid by weight', 'cubic yards from tons', 'how much space does material take', 'mass to volume'],
  fields: [mwSel('m', 'Material', mwList, String(MW.findIndex(r => r[0] === 'Water, fresh (20 °C)'))), F('cd', 'Custom density', '', 'kg/m³', { opt: 1 }), SEL('u', 'Mass unit', [['1', 'kilograms'], ['0.45359237', 'pounds'], ['1000', 'tonnes'], ['907.18474', 'short tons'], ['1016.0469088', 'long tons']], '0.45359237'), F('x', 'Mass', 500)],
  run: v => { const d = mwDens(v.m, v.cd); if (!d) return { err: 'Enter a custom density above 0.' }; if (!(v.x >= 0)) return { err: 'Mass must be 0 or more.' }; const m = v.x * parseFloat(v.u), V = m / d; return [['Volume', V * 1000, 'L'], ['Volume', V * 264.172052, 'US gal'], ['Volume', V * 219.969157, 'imperial gal'], ['Volume', V, 'm³'], ['Volume', V * 35.3146667, 'ft³'], ['Volume', V * 1.30795062, 'yd³'], ['Volume', V * 6.28981077, 'barrels (42 US gal)'], mwA('solid material or liquid at a density of ' + fmt(d, 5) + ' kg/m³; for loose aggregates use the bulk-density calculator, which uses the bulk (not the solid) density.')]; } });
