const FIG_SVTRAV = FIG(SV(340, 180, 'Traverse that does not close: the computed end point misses the starting point by the misclosure',
  geoDef('tv') + `<polyline fill="none" stroke="currentColor" stroke-width="2" points="60,140 60,50 190,50 270,110 120,140"/><circle cx="60" cy="140" r="4" fill="${ACC}"/><circle cx="120" cy="140" r="4" fill="none" stroke="${ACC}"/>` + geoArr('tv', 118, 150, 66, 150) + sLab(60, 162, 'start') + ppT(104, 162, 'computed end', ACC) + ppS(180, 140, 'misclosure') + ppS(12, 20, 'Σ latitudes = ΔN error, Σ departures = ΔE error') + ppS(12, 34, 'precision = perimeter ÷ misclosure')),
  'A closed traverse should return to its start. The gap is the misclosure; the ratio of precision compares it to the perimeter.');
const SV_TERMS = [['Azimuth', 'Horizontal angle measured clockwise from a north reference, 0–360°.'], ['Bearing', 'Direction given as a quadrant (N/S), an acute angle, and E/W.'], ['Back azimuth', 'Azimuth of the reverse direction: azimuth ± 180°.'], ['Northing / Easting', 'Rectangular coordinates measured north and east from an origin.'], ['Latitude (traverse)', 'North-south component of a line: D cos Az. (Not geographic latitude.)'], ['Departure', 'East-west component of a line: D sin Az.'], ['Latitude / longitude', 'Angular position on the earth, measured from the equator and the prime meridian.'], ['Datum', 'Reference surface or system for positions (NAD83, WGS 84) or elevations (NAVD 88).'], ['Benchmark (BM)', 'Marked point of known elevation.'], ['Backsight (BS)', 'Reading on a point of known elevation or position to establish the instrument reference.'], ['Foresight (FS)', 'Reading on a new point whose elevation or position is wanted.'], ['Height of instrument (HI)', 'Elevation of the level line of sight: BM elevation + BS.'], ['Turning point', 'Temporary point used to carry elevation to the next setup.'], ['Contour', 'Line of equal elevation on a map.'], ['Contour interval', 'Vertical difference between adjacent contours.'], ['Index contour', 'Heavier contour labelled with elevation, usually every fifth.'], ['Map scale', 'Ratio of map distance to ground distance (1:24,000 means 1 unit = 24,000 units).'], ['Representative fraction (RF)', 'Scale as a unitless ratio.'], ['Large scale map', 'Small denominator (1:1,000): more detail, smaller area.'], ['Triangulation', 'Positioning by measuring angles in triangles from a known baseline.'], ['Trilateration', 'Positioning by measuring distances only.'], ['Traverse', 'Series of connected lines with measured lengths and angles.'], ['Closure / misclosure', 'Amount by which a computed traverse fails to close on its start.'], ['Ratio of precision', 'Perimeter ÷ misclosure, written 1:N.'], ['Bowditch (compass) rule', 'Adjustment that distributes closure error in proportion to line lengths.'], ['Plat', 'Recorded map of a subdivision of land.'], ['Metes and bounds', 'Legal description using bearings and distances from a point of beginning.'], ['Monument', 'Physical marker of a corner (rebar, pin, stone).'], ['Zenith angle', 'Vertical angle measured down from straight up (0° = zenith).'], ['Slope distance', 'Distance measured along the ground; horizontal distance is its reduced length.'], ['Curvature and refraction', 'Earth curvature and atmospheric bending that affect long levelling sights and vertical angles.'], ['Magnetic declination', 'Angle between true north and magnetic north, varies by place and year.'], ['Grid convergence', 'Angle between grid north and true north at a point.'], ['Scale factor', 'Ratio of grid distance to ground distance in a projection.'], ['Elevation / orthometric height', 'Height above the geoid (approximately mean sea level).'], ['Ellipsoid height', 'Height above the reference ellipsoid (what raw GPS gives).'], ['RTK GNSS', 'Real-time kinematic satellite positioning with centimetre accuracy using a base or network.']];
