/* ===== Reference data registry + Formula Encyclopedia engine =====
   REG   : structured registries (formula now; term, notebook templates etc. in later phases).
   FORM  : curated formula entry with variables, units, conditions, worked example (computed by fn), related calculators/chapters.
   harvestFormulas(): adds every FX(...) block found in the chapters as a browsable entry (dedup by name). */
const DISC = ['Mathematics', 'Mechanical', 'Electrical', 'Construction', 'Fluid mechanics', 'Materials', 'Chemistry', 'Physics', 'Financial mathematics'];
const DISC_OTHER = 'General reference';
const CH_DISC = { fasteners: 'Mechanical', tools: 'Mechanical', 'rope-cable': 'Mechanical', automotive: 'Mechanical', 'pumps-tanks': 'Fluid mechanics', carpentry: 'Construction', 'steel-metals': 'Materials', 'materials-weights': 'Materials', surveying: 'Construction', electrical: 'Electrical', electronics: 'Electrical', math: 'Mathematics', 'mine-mill': 'Materials', welding: 'Materials', 'chem-phys': 'Physics', science: 'Physics', constants: 'Physics', 'glue-paints': 'Materials', geology: 'Materials', 'air-gases': 'Fluid mechanics', 'pipe-fittings': 'Fluid mechanics', water: 'Fluid mechanics', weather: 'Fluid mechanics', money: 'Financial mathematics', computers: 'Mathematics', conversions: 'Mathematics' };
const REG = {
  kinds: {},
  disciplines: DISC,
  define(kind, o) { this.kinds[kind] = Object.assign({ list: [], byId: {}, validate: () => { } }, o); return this.kinds[kind]; },
  add(kind, item) { const k = this.kinds[kind]; if (!k) throw new Error('unknown registry ' + kind); k.validate(item); if (k.byId[item.id]) throw new Error('duplicate ' + kind + ' id ' + item.id); k.list.push(item); k.byId[item.id] = item; return item; },
  all(kind) { return this.kinds[kind].list; },
  get(kind, id) { return this.kinds[kind].byId[id]; },
  stats() { return Object.keys(this.kinds).map(k => [k, this.kinds[k].list.length]); }
};
APP.reg = REG;
REG.define('formula', {
  validate(f) {
    if (!f.id || !f.name || !f.eq) throw new Error('formula needs id, name, eq: ' + f.id);
    if (DISC.indexOf(f.disc) < 0) throw new Error('bad discipline for ' + f.id + ': ' + f.disc);
    if (f.fn) {
      const ins = f.vars.filter(v => v.k !== f.out).map(v => v.k);
      ins.forEach(k => { if (typeof f.ex[k] !== 'number') throw new Error('formula ' + f.id + ' example lacks ' + k); });
      if (!f.vars.some(v => v.k === f.out)) throw new Error('formula ' + f.id + ' has no output variable');
      const r = f.fn(f.ex); if (typeof r !== 'number' || !isFinite(r)) throw new Error('formula ' + f.id + ' example is not finite');
    }
  }
});
const fwNum = x => { if (!isFinite(x)) return '—'; const a = Math.abs(x); if (a !== 0 && (a >= 1e9 || a < 1e-4)) return x.toExponential(4).replace(/\.?0+e/, 'e').replace('e+', ' × 10^').replace('e-', ' × 10^-'); return String(+x.toPrecision(6)); };
/* FORM(id, name, discipline, equation text, 'key~symbol|definition|unit; …', conditions, output key, fn(values), example values, [calculator ids], [chapter ids], [aliases]) */
function FORM(id, name, disc, eq, vars, cond, out, fn, ex, calcs, chs, ab) {
  const vs = vars.split(';').map(s => s.trim()).filter(Boolean).map(s => { const p = s.split('|'), kk = p[0].split('~'); return { k: kk[0].trim(), s: (kk[1] || kk[0]).trim(), d: (p[1] || '').trim(), u: (p[2] || '').trim() }; });
  return REG.add('formula', { id, name, disc, eq, vars: vs, cond: cond || '', out, fn, ex: ex || {}, calcs: calcs || [], chs: chs || [], ab: ab || [], curated: true });
}
const fwExample = f => {
  if (!f.fn) return '';
  const ins = f.vars.filter(v => v.k !== f.out), o = f.vars.find(v => v.k === f.out);
  return 'Given ' + ins.map(v => v.s + ' = ' + fwNum(f.ex[v.k]) + (v.u ? ' ' + v.u : '')).join(', ') + ', the result is ' + o.s + ' = ' + fwNum(f.fn(f.ex)) + (o.u ? ' ' + o.u : '') + '.';
};
function formulaNorm(s) { return String(s).toLowerCase().replace(/<[^>]+>/g, '').replace(/&[a-z]+;/g, ' ').replace(/[^a-z0-9µ°²³.+\-\/ ]+/g, ' ').replace(/\s+/g, ' ').trim(); }
function harvestFormulas() {
  const have = new Map(); REG.all('formula').forEach(f => have.set(formulaNorm(f.name), f));
  const out = [], seen = new Map(), usedH = new Set();
  APP.chapters.forEach(c => c.sections.forEach(s => {
    const re = /<div class="fx"><b>([^<]+)<\/b><code>([\s\S]*?)<\/code>(?:<span>([\s\S]*?)<\/span>)?<\/div>/g; let m;
    while ((m = re.exec(s.html))) {
      const name = unesc(m[1]).replace(/^[\s>•·\-–—:]+/, '').trim(), key = formulaNorm(name) + '|' + formulaNorm(m[2]);
      if (!name) continue;
      const cur = have.get(formulaNorm(name));
      if (cur) { cur.locs = cur.locs || []; if (!cur.locs.some(l => l.ch === c.id && l.sec === s.id)) cur.locs.push({ ch: c.id, sec: s.id }); continue; }
      if (seen.has(key)) { seen.get(key).locs.push({ ch: c.id, sec: s.id }); continue; }
      let disc = CH_DISC[c.id] || DISC_OTHER; const nl = name.toLowerCase();
      if (/molar|molality|ph\b|mole|titrat|stoich|dilution|solute|acid|equilibrium|enthalpy/.test(nl)) disc = 'Chemistry';
      let hid = ('h:' + formulaNorm(name).replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')).slice(0, 70); while (usedH.has(hid)) hid += '-2'; usedH.add(hid);
      const e = { id: hid, name, disc, eq: m[2], note: m[3] || '', locs: [{ ch: c.id, sec: s.id }], harvested: true, vars: [], calcs: [], chs: [c.id], ab: [] };
      seen.set(key, e); out.push(e);
    }
  }));
  return out;
}
/* ===== Formula data A: Mathematics, Mechanical, Electrical ===== */
const D2 = Math.PI / 180;
// ---- Mathematics
FORM('quadratic', 'Quadratic formula', 'Mathematics', 'x = (−b ± √(b² − 4ac)) ÷ 2a', 'a|coefficient of x²|; b|coefficient of x|; c|constant term|; x~x₁|larger real root|', 'a ≠ 0; real roots need b² − 4ac ≥ 0.', 'x', v => (-v.b + Math.sqrt(v.b * v.b - 4 * v.a * v.c)) / (2 * v.a), { a: 1, b: -3, c: 2 }, ['quadratic'], ['math'], ['roots', 'second degree equation']);
FORM('pythagoras', 'Pythagorean theorem', 'Mathematics', 'c² = a² + b²', 'a|first leg|length; b|second leg|length; c|hypotenuse|length', 'Right triangle only; c is opposite the right angle.', 'c', v => Math.hypot(v.a, v.b), { a: 3, b: 4 }, ['triangle'], ['math'], ['right triangle', '3-4-5']);
FORM('law-cos', 'Law of cosines', 'Mathematics', 'c² = a² + b² − 2ab cos C', 'a|side|length; b|side|length; C|angle between a and b|°; c|side opposite C|length', 'Any triangle.', 'c', v => Math.sqrt(v.a * v.a + v.b * v.b - 2 * v.a * v.b * Math.cos(v.C * D2)), { a: 5, b: 7, C: 60 }, ['triangle'], ['math']);
FORM('law-sin', 'Law of sines', 'Mathematics', 'a ÷ sin A = b ÷ sin B = c ÷ sin C', 'a|side opposite A|length; A|angle opposite a|°; B|angle opposite b|°; b|side opposite B|length', 'Any triangle; ambiguous when two sides and a non-included angle are known.', 'b', v => v.a * Math.sin(v.B * D2) / Math.sin(v.A * D2), { a: 10, A: 30, B: 45 }, ['triangle'], ['math']);
FORM('heron', 'Triangle area (Heron)', 'Mathematics', 'A = √[s(s − a)(s − b)(s − c)],  s = (a + b + c) ÷ 2', 'a|side|length; b|side|length; c|side|length; A|area|length²', 'The three sides must satisfy the triangle inequality.', 'A', v => { const s = (v.a + v.b + v.c) / 2; return Math.sqrt(s * (s - v.a) * (s - v.b) * (s - v.c)); }, { a: 3, b: 4, c: 5 }, ['triangle'], ['math']);
FORM('circle-area', 'Area of a circle', 'Mathematics', 'A = π r²', 'r|radius|length; A|area|length²', '', 'A', v => Math.PI * v.r * v.r, { r: 5 }, ['circle-seg'], ['math'], ['disc']);
FORM('circumference', 'Circumference of a circle', 'Mathematics', 'C = 2π r', 'r|radius|length; C|circumference|length', '', 'C', v => 2 * Math.PI * v.r, { r: 5 }, ['circle-seg'], ['math']);
FORM('sphere-vol', 'Volume of a sphere', 'Mathematics', 'V = (4/3) π r³', 'r|radius|length; V|volume|length³', '', 'V', v => 4 / 3 * Math.PI * v.r ** 3, { r: 3 }, ['vol-calc'], ['math']);
FORM('cyl-vol', 'Volume of a cylinder', 'Mathematics', 'V = π r² h', 'r|radius|length; h|height|length; V|volume|length³', 'Right circular cylinder.', 'V', v => Math.PI * v.r * v.r * v.h, { r: 2, h: 10 }, ['vol-calc'], ['math']);
FORM('trapezoid', 'Area of a trapezoid', 'Mathematics', 'A = (a + b) h ÷ 2', 'a|parallel side|length; b|parallel side|length; h|height between them|length; A|area|length²', 'Two sides parallel; h is measured perpendicular to them.', 'A', v => (v.a + v.b) * v.h / 2, { a: 4, b: 6, h: 3 }, ['area-calc'], ['math']);
FORM('arith-sum', 'Sum of an arithmetic series', 'Mathematics', 'S = n (a₁ + aₙ) ÷ 2', 'n|number of terms|; a1~a₁|first term|; an~aₙ|last term|; S|sum|', 'Constant difference between terms.', 'S', v => v.n * (v.a1 + v.an) / 2, { n: 10, a1: 1, an: 10 }, [], ['math']);
FORM('geom-sum', 'Sum of a geometric series', 'Mathematics', 'S = a (1 − rⁿ) ÷ (1 − r)', 'a|first term|; r|common ratio|; n|number of terms|; S|sum|', 'r ≠ 1.', 'S', v => v.a * (1 - v.r ** v.n) / (1 - v.r), { a: 1, r: 2, n: 10 }, [], ['math']);
FORM('slope-line', 'Slope of a line', 'Mathematics', 'm = (y₂ − y₁) ÷ (x₂ − x₁)', 'x1~x₁|first point x|; y1~y₁|first point y|; x2~x₂|second point x|; y2~y₂|second point y|; m|slope|', 'x₂ ≠ x₁ (otherwise the line is vertical).', 'm', v => (v.y2 - v.y1) / (v.x2 - v.x1), { x1: 1, y1: 2, x2: 5, y2: 10 }, ['linear2'], ['math']);
FORM('distance-pts', 'Distance between two points', 'Mathematics', 'd = √[(x₂ − x₁)² + (y₂ − y₁)²]', 'x1~x₁|first x|; y1~y₁|first y|; x2~x₂|second x|; y2~y₂|second y|; d|distance|length', 'Flat (Cartesian) plane.', 'd', v => Math.hypot(v.x2 - v.x1, v.y2 - v.y1), { x1: 0, y1: 0, x2: 3, y2: 4 }, ['sv-dist', 'coord-inverse'], ['math']);
FORM('mean', 'Arithmetic mean', 'Mathematics', 'x̄ = Σx ÷ n', 'sum~Σx|sum of all values|; n|number of values|; xbar~x̄|mean|', 'n > 0.', 'xbar', v => v.sum / v.n, { sum: 99, n: 7 }, ['stats'], ['math'], ['average']);
FORM('std-dev', 'Population standard deviation', 'Mathematics', 'σ = √[Σ(x − μ)² ÷ N]', 'ss~Σ(x−μ)²|sum of squared deviations|; N|number of values|; sigma~σ|standard deviation|', 'Whole population; divide by N − 1 for a sample.', 'sigma', v => Math.sqrt(v.ss / v.N), { ss: 32, N: 8 }, ['stats'], ['math']);
FORM('pct-change', 'Percent change', 'Mathematics', 'Δ% = (new − old) ÷ old × 100', 'old|original value|; new|new value|; pct~Δ%|percent change|%', 'old ≠ 0.', 'pct', v => (v.new - v.old) / v.old * 100, { old: 80, new: 100 }, ['percent-change'], ['math']);
FORM('combinations', 'Combinations', 'Mathematics', 'C(n, k) = n! ÷ [k! (n − k)!]', 'n|items available|; k|items chosen|; C|number of combinations|', 'Whole numbers, 0 ≤ k ≤ n; order does not matter.', 'C', v => { const f = x => { let r = 1; for (let i = 2; i <= x; i++) r *= i; return r; }; return f(v.n) / (f(v.k) * f(v.n - v.k)); }, { n: 5, k: 2 }, [], ['math']);
FORM('deg-rad', 'Degrees to radians', 'Mathematics', 'rad = deg × π ÷ 180', 'deg|angle|°; rad|angle|rad', 'Angle in degrees; the result is in radians (360° = 2π rad).', 'rad', v => v.deg * Math.PI / 180, { deg: 180 }, ['angle-dms'], ['math']);
