    const tOpt = Object.keys(KTYPE).map(k => `<option value="${k}">${KTYPE[k][0]}</option>`).join(''), cOpt = Object.keys(KCAT).map(k => `<option value="${k}">${KCAT[k]}</option>`).join('');
