const KEYS = ['bm', 'rec', 'theme', 'fs', 'notes', 'open', 'cv', 'cvu', 'last', 'nb'];
const st = { bm: store.get('bm', []), rec: store.get('rec', []), theme: store.get('theme2', 'light'), fs: store.get('fs', 1), notes: store.get('notes', {}), open: store.get('open', {}), cv: store.get('cv', {}), cvu: store.get('cvu', {}), last: store.get('last', ''), tb: store.get('tb', {}) };
{ const raw = store.get('nb', {}); st.nb = nbEmpty(); ['notes', 'entries', 'formulas', 'results'].forEach(k => { (raw && Array.isArray(raw[k]) ? raw[k] : []).forEach(x => { const c = nbClean(k, x); if (c) st.nb[k].push(c); }); }); }
