    const h = APP.calcHome[c.id]; if (!h) return;
    const text = (c.desc || '') + ' ' + c.fields.map(f => f.l).join(' ') + ' ' + (c.kw || []).join(' ');
    DOCS.push({ type: 'calc', ch: h.ch, sec: h.sec, calc: c.id, title: c.title, chTitle: APP.byId[h.ch].title, kw: (c.kw || []).join(' '), text, lt: c.title.toLowerCase(), lk: (c.kw || []).join(' ').toLowerCase(), lx: text.toLowerCase(), lc: APP.byId[h.ch].title.toLowerCase() });
