  $$('[data-y]', el).forEach(b => b.addEventListener('click', () => { const dy = +b.dataset.y; showYear(dy === 0 ? today.y : (+$('#cy', el).value || today.y) + dy); }));
  $('#cy', el).addEventListener('change', e => showYear(+e.target.value));
