    let list = FE.filter(f => (dsel === 'All' || f.disc === dsel) && (src === 'All' || (src === 'curated' ? !f.harvested : f.harvested)) && (!q || (toks.length ? toks.every(t => feHit(f, t)) : (f.name + ' ' + fePlain(f.eq) + ' ' + f.vars.map(v => v.s).join(' ')).toLowerCase().includes(q.toLowerCase()))));
