    shown.forEach(f => {
      if (!toks.length) { const g = mode === 'disc' ? f.disc : feLetter(f.name); if (g !== last) { last = g; h += `<h3 class="fe-h">${esc(g)}</h3>`; } }
      h += `<details class="fe-e" data-id="${f.id}"><summary><b>${ixHL(f.name, toks)}</b> <code>${f.eq.length > 90 ? esc(fePlain(f.eq).slice(0, 88)) + '…' : f.eq}</code> <small>${esc(f.disc)}${f.harvested ? ' · chapter' : ''}</small></summary><div class="fe-b"></div></details>`;
    });
    if (!shown.length) h = '<p>No formulas match. Try a shorter word, a symbol name (for example <i>ohm</i>, <i>torque</i>, <i>pH</i>) or choose “All”.</p>';
    if (list.length > cap) h += `<p><small>Showing the first ${cap} of ${list.length} matches; type more letters to narrow.</small></p>`;
    $('.fel', el).innerHTML = h;
    $('.fec', el).textContent = list.length + ' formula' + (list.length === 1 ? '' : 's') + ' (' + FE.length + ' in total, ' + REG.all('formula').length + ' with worked examples)';
