    const b = e.target.closest && e.target.closest('[data-nb]'); if (!b) return; const a = b.dataset.nb, item = b.closest('.nb-i'), kind = item && item.dataset.k;
    if (a === 'add-note') { const t = $('.nb-t', el).value, body = $('.nb-b', el).value, tags = $('.nb-tags', el).value.split(',').map(x => x.trim()).filter(Boolean); if (!t.trim() && !body.trim()) { toast('Write a title or some text first'); return; } nbAdd('notes', { title: t, body, tags }); rerenderKeep(); toast('Note added'); return; }
    if (a === 'add-entry') { const t = $('.nb-t', el).value; if (!t.trim()) { toast('An entry needs a title'); return; } nbAdd('entries', { title: t, disc: $('.nb-d', el).value, abbr: $('.nb-a', el).value, eq: $('.nb-e', el).value, body: $('.nb-b', el).value }); rerenderKeep(); toast('Entry added'); return; }
    if (a === 'del') { if (b.dataset.armed) { st.nb[kind] = st.nb[kind].filter(x => x.id !== b.dataset.id); nbSave(); rerenderKeep(); toast('Deleted'); } else { b.dataset.armed = '1'; b.textContent = 'Click again to delete'; setTimeout(() => { if (b.isConnected) { b.dataset.armed = ''; b.textContent = 'Delete'; } }, 3000); } return; }
    if (a === 'unbm') { st.bm = st.bm.filter(x => x !== b.dataset.key); save('bm'); rerenderKeep(); return; }
    if (a === 'copy') { const n = st.nb.results.find(x => x.id === b.dataset.id); if (n) copyText(n.text); return; }
    if (a === 'restore') { const n = st.nb.results.find(x => x.id === b.dataset.id); if (n && APP.calcs[n.calc]) { st.cv[n.calc] = Object.assign({}, n.inputs); save('cv'); const h = APP.calcHome[n.calc]; toast('Inputs restored'); location.hash = '#' + h.ch + '--' + h.sec; } return; }
    if (a === 'dl') { nbDownload(); return; }
