  var pick = el.length <= 4 ? el : [0, 1, 2, 3].map(function (i) { return el[Math.floor(i * el.length / 4)]; });
  var probs = [];
  pick.forEach(function (c) {
    var vals = tbVariant(c, 1), x = tbRunCalc(c, vals); if (!x) { vals = tbVariant(c, 2); x = tbRunCalc(c, vals); }
    if (!x) { x = tbRunCalc(c, tbDefaults(c)); }
    if (!x) return;
    var f = forms.find(function (z) { return z.calcs && z.calcs.indexOf(c.id) >= 0; });
    probs.push({ kind: 'calc', title: c.title, given: x.given, ans: x.ans, hint: f ? f.name + ': ' + f.eq : (c.desc || '') });
  });
  var used = {}; pool.qs.slice(0, 5).forEach(function (q) { used[q.q] = 1; });
  var lk = pool.lookups.filter(function (x) { return !used[x.q]; });
  var need = Math.max(2, 5 - probs.length), seen = {};
